insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (53, 3, 93, 99, 'سورة آل عمران ٩٣ – ٩٩', 'حِلّ الطعام، والبيت الحرام، وفرض الحج', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 53) = $j$[{"lbl": "الآيات ٩٣ – ٩٧", "q": "۞كُلُّ ٱلطَّعَامِ كَانَ حِلّٗا لِّبَنِيٓ إِسۡرَـٰٓءِيلَ إِلَّا مَا حَرَّمَ إِسۡرَـٰٓءِيلُ عَلَىٰ نَفۡسِهِۦ مِن قَبۡلِ أَن تُنَزَّلَ ٱلتَّوۡرَىٰةُۚ قُلۡ فَأۡتُواْ بِٱلتَّوۡرَىٰةِ فَٱتۡلُوهَآ إِن كُنتُمۡ صَٰدِقِينَ ﴿٩٣﴾ فَمَنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ ٱلۡكَذِبَ مِنۢ بَعۡدِ ذَٰلِكَ فَأُوْلَـٰٓئِكَ هُمُ ٱلظَّـٰلِمُونَ ﴿٩٤﴾ قُلۡ صَدَقَ ٱللَّهُۗ فَٱتَّبِعُواْ مِلَّةَ إِبۡرَٰهِيمَ حَنِيفٗاۖ وَمَا كَانَ مِنَ ٱلۡمُشۡرِكِينَ ﴿٩٥﴾ إِنَّ أَوَّلَ بَيۡتٖ وُضِعَ لِلنَّاسِ لَلَّذِي بِبَكَّةَ مُبَارَكٗا وَهُدٗى لِّلۡعَٰلَمِينَ ﴿٩٦﴾ فِيهِ ءَايَٰتُۢ بَيِّنَٰتٞ مَّقَامُ إِبۡرَٰهِيمَۖ وَمَن دَخَلَهُۥ كَانَ ءَامِنٗاۗ وَلِلَّهِ عَلَى ٱلنَّاسِ حِجُّ ٱلۡبَيۡتِ مَنِ ٱسۡتَطَاعَ إِلَيۡهِ سَبِيلٗاۚ وَمَن كَفَرَ فَإِنَّ ٱللَّهَ غَنِيٌّ عَنِ ٱلۡعَٰلَمِينَ ﴿٩٧﴾", "w": [["الطعام", "اسم لكل ما يُطعم من أنواع المأكولات."], ["حِلّاً", "حلالاً، وسُمّي كذلك لانحلال عقدة الحظر عنه."], ["بني إسرائيل", "أولاد يعقوب الملقّب بإسرائيل، المنحدرون من أبنائه الاثني عشر."], ["حرّم", "حظر ومنع."], ["فاتلوها", "اقرؤوها على رؤوس الملأ ليتبيّن صدق دعواكم من بطلانها."], ["افترى الكذب", "اختلقه وزوّره."], ["ملة إبراهيم", "دينه، وهي عبادة الله بما شرع ونبذ الشرك والبدع."], ["حنيفاً", "مائلاً عن الشرك إلى التوحيد."], ["ببكّة", "مكة."], ["للعالمين", "للناس أجمعين."], ["مقام إبراهيم", "الحجر الذي قام عليه أثناء بناء البيت فارتسمت عليه قدماه وهو صخر."], ["ومن دخله", "الحرم الذي حول البيت بحدوده المعروفة."], ["آمناً", "لا يُخاف على نفس ولا مال ولا عرض."], ["حجّ البيت", "قصد البيت للطواف به وأداء بقية المناسك."], ["سبيلاً", "القدرة على السير إلى البيت والقيام بالمناسك."]], "m": "ما زال السياق في الحِجاج مع أهل الكتاب: قال اليهود للنبي ﷺ: كيف تدّعي أنك على دين إبراهيم وتأكل لحوم الإبل وألبانها المحرّمة في دينه؟ فردّ الله: كل الطعام كان حلالاً لبني إسرائيل إلا ما حرّم يعقوب على نفسه خاصة، وهو لحوم الإبل وألبانها، لنذرٍ نذره إن شفاه الله أن يترك أحب الطعام إليه، وكان ذلك قبل أن تنزل التوراة بقرون؛ فأتوا بالتوراة فاقرؤوها، فستجدون أن ما حُرّم على اليهود إنما كان لظلمهم بعد إبراهيم ويعقوب. فلما طولبوا بها بُهتوا ولم يفعلوا، فقامت الحجة عليهم، ومن افترى على الله الكذب بعد ذلك فأولئك هم الظالمون. قل صدق الله، فاتّبعوا ملة إبراهيم حنيفاً وما كان من المشركين.\nوردّ على قولهم إن بيت المقدس أول قبلة، فأخبر أن أول بيت وُضع للناس هو الكعبة ببكّة، جعله مباركاً لا تفارقه البركة، وهدى للعالمين يحجّونه ويستقبلونه في صلاتهم. فيه آيات بيّنات، منها مقام إبراهيم وزمزم والصفا والمروة وسائر المشاعر، ومنها الأمن لمن دخله، جعل الله حرمته في قلوب العرب وهم في جاهليتهم. ثم فرض حجّه بأبلغ صيغ الإيجاب: «ولله على الناس حج البيت من استطاع إليه سبيلاً»، واستثنى العاجزين بمرض أو خوف أو قلة نفقة، ومن كفر فلا يضر إلا نفسه، فإن الله غني عن العالمين.", "h": ["ثبوت النسخ في الشرائع الإلهية؛ إذ حرّم الله على اليهود بعض ما كان حلالاً لهم.", "إبطال دعوى اليهود أن إبراهيم ﵇ كان محرّماً عليه لحوم الإبل وألبانها.", "تقرير النبوة المحمدية بتحدّي اليهود وعجزهم عن دفع الحق الذي جاء به محمد ﷺ.", "البيت الحرام كان قبل بيت المقدس، وهو أول بيت وُضع للتعبد بالطواف به.", "مشروعية طلب البركة بزيارة البيت وحجّه والطواف به والتعبد حوله.", "وجوب الحج على الفور لمن لم يكن له مانع يمنعه.", "الإشارة إلى كفر من يترك الحج وهو قادر عليه ولا مانع له غير عدم المبالاة."], "k": "إن كنتُ مستطيعاً ولم أحجّ بعد… فما الذي يؤخّرني؟ وإن لم أستطع، فهل نويته بصدق؟"}, {"lbl": "الآيتان ٩٨ – ٩٩", "q": "قُلۡ يَـٰٓأَهۡلَ ٱلۡكِتَٰبِ لِمَ تَكۡفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَٱللَّهُ شَهِيدٌ عَلَىٰ مَا تَعۡمَلُونَ ﴿٩٨﴾ قُلۡ يَـٰٓأَهۡلَ ٱلۡكِتَٰبِ لِمَ تَصُدُّونَ عَن سَبِيلِ ٱللَّهِ مَنۡ ءَامَنَ تَبۡغُونَهَا عِوَجٗا وَأَنتُمۡ شُهَدَآءُۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعۡمَلُونَ ﴿٩٩﴾", "w": [["آيات الله", "ما أنزل الله من الحجج في القرآن، وفي التوراة والإنجيل من صفات النبي ﷺ الموجبة للإيمان به."], ["شهيد على ما تعملون", "عليم به مطّلع عليه."], ["تصدّون عن سبيل الله", "تصرفون الناس عن الإسلام الذي هو سبيل الله المفضي إلى سعادة الدارين."], ["تبغونها عوجاً", "تطلبون لها الاعوجاج بالتحريف والتضليل، فيضلّ سالكها."], ["وأنتم شهداء", "عالمون بأن الإسلام حق، وأن ما تفعلونه كفر وباطل."]], "m": "بعد أن دحض الله شبه أهل الكتاب، أمر رسوله أن يقول لهم موبّخاً: يا أهل الكتاب، لمَ تكفرون بحجج الله المثبتة لنبوة محمد ﷺ ودينه، التي جاء بها القرآن والتوراة والإنجيل معاً، والله مطّلع على كفركم؟ أما تخافون عقابه؟ وأن يقول لهم: يا أهل العلم الأول، لمَ تصرفون المؤمنين عن الإسلام بما تثيرونه من الشكوك والأوهام، تطلبون له العوج، وأنتم تعلمون صحته وصدق نبيّه؟ وما الله بغافل عن مكركم وخداعكم.", "h": ["شدة قبح كفر من كان عالماً من أهل الكتاب بالحق ثم جحده بغياً وحسداً.", "حرمة صرف الناس عن الحق والمعروف بأنواع الحيل والكذب والخداع.", "علم الله بكل أعمال عباده من خير وشر، وسيجزيهم بها فضلاً منه وعدلاً."], "k": "هل أثرتُ يوماً شكاً في قلب أحد عن الخير، ولو بكلمة ساخرة؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 53;
