insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (54, 3, 100, 109, 'سورة آل عمران ١٠٠ – ١٠٩', 'الاعتصام بحبل الله، والدعوة إلى الخير', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 54) = $j$[{"lbl": "الآيات ١٠٠ – ١٠٣", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِن تُطِيعُواْ فَرِيقٗا مِّنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ يَرُدُّوكُم بَعۡدَ إِيمَٰنِكُمۡ كَٰفِرِينَ ﴿١٠٠﴾ وَكَيۡفَ تَكۡفُرُونَ وَأَنتُمۡ تُتۡلَىٰ عَلَيۡكُمۡ ءَايَٰتُ ٱللَّهِ وَفِيكُمۡ رَسُولُهُۥۗ وَمَن يَعۡتَصِم بِٱللَّهِ فَقَدۡ هُدِيَ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ ﴿١٠١﴾ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ حَقَّ تُقَاتِهِۦ وَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسۡلِمُونَ ﴿١٠٢﴾ وَٱعۡتَصِمُواْ بِحَبۡلِ ٱللَّهِ جَمِيعٗا وَلَا تَفَرَّقُواْۚ وَٱذۡكُرُواْ نِعۡمَتَ ٱللَّهِ عَلَيۡكُمۡ إِذۡ كُنتُمۡ أَعۡدَآءٗ فَأَلَّفَ بَيۡنَ قُلُوبِكُمۡ فَأَصۡبَحۡتُم بِنِعۡمَتِهِۦٓ إِخۡوَٰنٗا وَكُنتُمۡ عَلَىٰ شَفَا حُفۡرَةٖ مِّنَ ٱلنَّارِ فَأَنقَذَكُم مِّنۡهَاۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمۡ ءَايَٰتِهِۦ لَعَلَّكُمۡ تَهۡتَدُونَ ﴿١٠٣﴾", "w": [["فريقاً", "طائفة من الحاقدين على الإسلام العاملين على الكيد له ولأهله."], ["يردّوكم", "يرجعوكم إلى الكفر بعد إيمانكم."], ["وكيف تكفرون", "استفهام للإنكار والتعجب من كفرهم بعد إيمانهم."], ["يعتصم", "يتمسّك بشدة."], ["حق تقاته", "باستفراغ الوسع في امتثال أمره واجتناب نهيه."], ["حبل الله", "كتابه ودينه الإسلام؛ لأنهما الصلة التي تربط المسلم بربه."], ["ألّف بين قلوبكم", "جمعها على أخوّة الإيمان بعد الاختلاف والنفرة."], ["شفا حفرة", "حافتها وطرفها، بحيث لو غفل الواقف عليها وقع فيها."], ["أنقذكم منها", "بهدايتكم إلى الإسلام، فأنجاكم من النار."]], "m": "بعد أن وبّخ الله اليهود على تضليلهم للمؤمنين، نادى المؤمنين محذّراً إياهم من شباكهم: «إن تطيعوا فريقاً من الذين أوتوا الكتاب يردّوكم بعد إيمانكم كافرين». وذلك أن نفراً من الأوس والخزرج كانوا في مجلس يسوده الود ببركة الإسلام، فمرّ بهم شاس بن قيس اليهودي فآلمه ذلك، فأمر شاباً أن يذكّرهم بيوم بُعاث، فتناشدوا الشعر وثارت الحمية حتى همّوا بالقتال، فأتاهم الرسول ﷺ وذكّرهم بالله فهدؤوا، ونزلت هذه الآيات. ثم قال متعجباً: وكيف تكفرون وأنتم تُتلى عليكم آيات الله وفيكم رسوله؟ ومن يعتصم بالله، بكتابه وسنة نبيه، فقد هُدي إلى صراط مستقيم. ثم ناداهم وأمرهم أن يتقوه حق تقاته، بامتثال أمره واجتناب نهيه، ويثبتوا على دينه حتى يموتوا عليه، وأمرهم بالاعتصام بحبله جميعاً، ونهاهم عن التفرق، وذكّرهم بنعمته إذ كانوا أعداء فألّف بين قلوبهم فأصبحوا إخواناً، وكانوا على شفا حفرة من النار، لو مات أحدهم يومئذ لوقع فيها، فأنقذهم منها.", "h": ["طاعة كثير من علماء اليهود والنصارى، بالأخذ بنصائحهم وتوجيهاتهم، تؤدّي بالمسلم إلى الكفر شعر أو لم يشعر، فوجب الحذر منهم.", "العصمة في التمسك بكتاب الله وسنة رسوله ﷺ، فمن تمسّك بهما لم يضل.", "الأخذ بالإسلام جملةً عقيدةً وشريعة أمان من الزيغ والضلال والهلاك.", "وجوب التمسك بالدين الإسلامي، وحرمة الفرقة والاختلاف فيه.", "وجوب ذكر النعم لأجل شكر الله عليها بطاعته وطاعة رسوله ﷺ.", "الإقامة على الشرك والمعاصي وقوف على شفير جهنم، فمن مات على ذلك وقع فيها."], "k": "«فأصبحتم بنعمته إخواناً»… مع من بيني وبينه خصام قديم، وهل أبدأ أنا بالصلح؟"}, {"lbl": "الآيات ١٠٤ – ١٠٩", "q": "وَلۡتَكُن مِّنكُمۡ أُمَّةٞ يَدۡعُونَ إِلَى ٱلۡخَيۡرِ وَيَأۡمُرُونَ بِٱلۡمَعۡرُوفِ وَيَنۡهَوۡنَ عَنِ ٱلۡمُنكَرِۚ وَأُوْلَـٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ ﴿١٠٤﴾ وَلَا تَكُونُواْ كَٱلَّذِينَ تَفَرَّقُواْ وَٱخۡتَلَفُواْ مِنۢ بَعۡدِ مَا جَآءَهُمُ ٱلۡبَيِّنَٰتُۚ وَأُوْلَـٰٓئِكَ لَهُمۡ عَذَابٌ عَظِيمٞ ﴿١٠٥﴾ يَوۡمَ تَبۡيَضُّ وُجُوهٞ وَتَسۡوَدُّ وُجُوهٞۚ فَأَمَّا ٱلَّذِينَ ٱسۡوَدَّتۡ وُجُوهُهُمۡ أَكَفَرۡتُم بَعۡدَ إِيمَٰنِكُمۡ فَذُوقُواْ ٱلۡعَذَابَ بِمَا كُنتُمۡ تَكۡفُرُونَ ﴿١٠٦﴾ وَأَمَّا ٱلَّذِينَ ٱبۡيَضَّتۡ وُجُوهُهُمۡ فَفِي رَحۡمَةِ ٱللَّهِۖ هُمۡ فِيهَا خَٰلِدُونَ ﴿١٠٧﴾ تِلۡكَ ءَايَٰتُ ٱللَّهِ نَتۡلُوهَا عَلَيۡكَ بِٱلۡحَقِّۗ وَمَا ٱللَّهُ يُرِيدُ ظُلۡمٗا لِّلۡعَٰلَمِينَ ﴿١٠٨﴾ وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ ﴿١٠٩﴾", "w": [["الأمّة", "الجماعة يجمعها أمر واحد، والمراد هنا المجاهدون وهيئات الأمر بالمعروف والنهي عن المنكر."], ["الخير", "الإسلام وكل ما ينفع الإنسان في دنياه وآخرته."], ["المعروف", "كل ما عرفه الشرع فأمر به لنفعه وصلاحه."], ["المنكر", "ضد المعروف، وهو ما نهى عنه الشرع لضرره وإفساده."], ["الذين تفرقوا", "أهل الكتاب من اليهود والنصارى."], ["يوم تبيضّ وجوه", "يوم القيامة."], ["ففي رحمة الله", "في الجنة."], ["نتلوها عليك بالحق", "نقرؤها عليك متلبّسة بالحق، لا باطل فيها."], ["وإلى الله تُرجع الأمور", "إليه تصير فيقضي فيها بما يشاء فضلاً وعدلاً."]], "m": "بعد أن أمر الله المؤمنين بتقواه والتمسك بدينه ونهاهم عن الفرقة، أمرهم أن تكون منهم جماعة تدعو إلى الإسلام بعرضه على الأمم والشعوب، وتأمر بالمعروف وتنهى عن المنكر في ديار الإسلام، وبشّرهم بأن الأمة التي تنهض بهذا هي المفلحة الفائزة بالنجاة من العار والنار. ثم نهاهم أن يسلكوا طريق أهل الكتاب في التفرق والاختلاف في الدين فيهلكوا هلاكهم؛ فلا ينبغي أن يكون العلم بشرائع الله سبباً في الفرقة وهو أداة الوحدة. وأخبرهم بجزاء المختلفين: عذاب عظيم يوم تبيضّ وجوه المؤمنين المؤتلفين على الكتاب والسنة، وتسودّ وجوه الكافرين المختلفين القائمين على البدع والأهواء؛ فأما الذين اسودّت وجوههم فيقال لهم توبيخاً: أكفرتم بعد إيمانكم؟ فذوقوا العذاب، وأما الذين ابيضّت وجوههم ففي رحمة الله هم فيها خالدون. ثم شرّف نبيه بخطابه: تلك آيات الله نتلوها عليك بالحق، فبلّغها، وما الله يريد ظلماً للعالمين، فلا يعذّب إلا بعد الإنذار. ولله ما في السماوات والأرض، وإليه تُرجع الأمور.", "h": ["وجوب وجود طائفة من أمة الإسلام تدعو الأمم والشعوب إلى الإسلام وتعرضه عليهم، ووجوب وجود هيئات الأمر بالمعروف والنهي عن المنكر في كل مدن المسلمين وقراهم.", "حرمة الفرقة بين المسلمين والاختلاف في دين الله.", "أهل البدع والأهواء يُعرفون في عرصات القيامة باسوداد وجوههم.", "أهل السنة والجماعة، الذين يعيشون عقيدةً وعبادةً على ما كان عليه رسول الله ﷺ وأصحابه، يُعرفون يوم العرض بابيضاض وجوههم.", "كرامة الرسول ﷺ على ربه وتقرير نبوته، وشرف من آمن به واتبعه.", "مرجع الأمور إلى الله في الدنيا والآخرة، فيجب على العقلاء أن يتخذوا عنده عهداً بالإيمان به وتوحيده."], "k": "«يدعون إلى الخير ويأمرون بالمعروف»… ما المعروف الذي أستطيع أن أدعو إليه في بيتي اليوم برفق؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 54;
insert into public.tdb_cards(topic, i, body) select 54, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٠٠ – ١٠٣", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِن تُطِيعُواْ فَرِيقٗا مِّنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ يَرُدُّوكُم بَعۡدَ إِيمَٰنِكُمۡ كَٰفِرِينَ ﴿١٠٠﴾ وَكَيۡفَ تَكۡفُرُونَ وَأَنتُمۡ تُتۡلَىٰ عَلَيۡكُمۡ ءَايَٰتُ ٱللَّهِ وَفِيكُمۡ رَسُولُهُۥۗ وَمَن يَعۡتَصِم بِٱللَّهِ فَقَدۡ هُدِيَ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ ﴿١٠١﴾ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ حَقَّ تُقَاتِهِۦ وَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسۡلِمُونَ ﴿١٠٢﴾ وَٱعۡتَصِمُواْ بِحَبۡلِ ٱللَّهِ جَمِيعٗا وَلَا تَفَرَّقُواْۚ وَٱذۡكُرُواْ نِعۡمَتَ ٱللَّهِ عَلَيۡكُمۡ إِذۡ كُنتُمۡ أَعۡدَآءٗ فَأَلَّفَ بَيۡنَ قُلُوبِكُمۡ فَأَصۡبَحۡتُم بِنِعۡمَتِهِۦٓ إِخۡوَٰنٗا وَكُنتُمۡ عَلَىٰ شَفَا حُفۡرَةٖ مِّنَ ٱلنَّارِ فَأَنقَذَكُم مِّنۡهَاۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمۡ ءَايَٰتِهِۦ لَعَلَّكُمۡ تَهۡتَدُونَ ﴿١٠٣﴾", "w": [["فريقاً", "طائفة من الحاقدين على الإسلام العاملين على الكيد له ولأهله."], ["يردّوكم", "يرجعوكم إلى الكفر بعد إيمانكم."], ["وكيف تكفرون", "استفهام للإنكار والتعجب من كفرهم بعد إيمانهم."], ["يعتصم", "يتمسّك بشدة."], ["حق تقاته", "باستفراغ الوسع في امتثال أمره واجتناب نهيه."], ["حبل الله", "كتابه ودينه الإسلام؛ لأنهما الصلة التي تربط المسلم بربه."], ["ألّف بين قلوبكم", "جمعها على أخوّة الإيمان بعد الاختلاف والنفرة."], ["شفا حفرة", "حافتها وطرفها، بحيث لو غفل الواقف عليها وقع فيها."], ["أنقذكم منها", "بهدايتكم إلى الإسلام، فأنجاكم من النار."]], "m": "بعد أن وبّخ الله اليهود على تضليلهم للمؤمنين، نادى المؤمنين محذّراً إياهم من شباكهم: «إن تطيعوا فريقاً من الذين أوتوا الكتاب يردّوكم بعد إيمانكم كافرين». وذلك أن نفراً من الأوس والخزرج كانوا في مجلس يسوده الود ببركة الإسلام، فمرّ بهم شاس بن قيس اليهودي فآلمه ذلك، فأمر شاباً أن يذكّرهم بيوم بُعاث، فتناشدوا الشعر وثارت الحمية حتى همّوا بالقتال، فأتاهم الرسول ﷺ وذكّرهم بالله فهدؤوا، ونزلت هذه الآيات. ثم قال متعجباً: وكيف تكفرون وأنتم تُتلى عليكم آيات الله وفيكم رسوله؟ ومن يعتصم بالله، بكتابه وسنة نبيه، فقد هُدي إلى صراط مستقيم. ثم ناداهم وأمرهم أن يتقوه حق تقاته، بامتثال أمره واجتناب نهيه، ويثبتوا على دينه حتى يموتوا عليه، وأمرهم بالاعتصام بحبله جميعاً، ونهاهم عن التفرق، وذكّرهم بنعمته إذ كانوا أعداء فألّف بين قلوبهم فأصبحوا إخواناً، وكانوا على شفا حفرة من النار، لو مات أحدهم يومئذ لوقع فيها، فأنقذهم منها.", "h": ["طاعة كثير من علماء اليهود والنصارى، بالأخذ بنصائحهم وتوجيهاتهم، تؤدّي بالمسلم إلى الكفر شعر أو لم يشعر، فوجب الحذر منهم.", "العصمة في التمسك بكتاب الله وسنة رسوله ﷺ، فمن تمسّك بهما لم يضل.", "الأخذ بالإسلام جملةً عقيدةً وشريعة أمان من الزيغ والضلال والهلاك.", "وجوب التمسك بالدين الإسلامي، وحرمة الفرقة والاختلاف فيه.", "وجوب ذكر النعم لأجل شكر الله عليها بطاعته وطاعة رسوله ﷺ.", "الإقامة على الشرك والمعاصي وقوف على شفير جهنم، فمن مات على ذلك وقع فيها."], "k": "«فأصبحتم بنعمته إخواناً»… مع من بيني وبينه خصام قديم، وهل أبدأ أنا بالصلح؟"}, {"lbl": "الآيات ١٠٤ – ١٠٩", "q": "وَلۡتَكُن مِّنكُمۡ أُمَّةٞ يَدۡعُونَ إِلَى ٱلۡخَيۡرِ وَيَأۡمُرُونَ بِٱلۡمَعۡرُوفِ وَيَنۡهَوۡنَ عَنِ ٱلۡمُنكَرِۚ وَأُوْلَـٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ ﴿١٠٤﴾ وَلَا تَكُونُواْ كَٱلَّذِينَ تَفَرَّقُواْ وَٱخۡتَلَفُواْ مِنۢ بَعۡدِ مَا جَآءَهُمُ ٱلۡبَيِّنَٰتُۚ وَأُوْلَـٰٓئِكَ لَهُمۡ عَذَابٌ عَظِيمٞ ﴿١٠٥﴾ يَوۡمَ تَبۡيَضُّ وُجُوهٞ وَتَسۡوَدُّ وُجُوهٞۚ فَأَمَّا ٱلَّذِينَ ٱسۡوَدَّتۡ وُجُوهُهُمۡ أَكَفَرۡتُم بَعۡدَ إِيمَٰنِكُمۡ فَذُوقُواْ ٱلۡعَذَابَ بِمَا كُنتُمۡ تَكۡفُرُونَ ﴿١٠٦﴾ وَأَمَّا ٱلَّذِينَ ٱبۡيَضَّتۡ وُجُوهُهُمۡ فَفِي رَحۡمَةِ ٱللَّهِۖ هُمۡ فِيهَا خَٰلِدُونَ ﴿١٠٧﴾ تِلۡكَ ءَايَٰتُ ٱللَّهِ نَتۡلُوهَا عَلَيۡكَ بِٱلۡحَقِّۗ وَمَا ٱللَّهُ يُرِيدُ ظُلۡمٗا لِّلۡعَٰلَمِينَ ﴿١٠٨﴾ وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ ﴿١٠٩﴾", "w": [["الأمّة", "الجماعة يجمعها أمر واحد، والمراد هنا المجاهدون وهيئات الأمر بالمعروف والنهي عن المنكر."], ["الخير", "الإسلام وكل ما ينفع الإنسان في دنياه وآخرته."], ["المعروف", "كل ما عرفه الشرع فأمر به لنفعه وصلاحه."], ["المنكر", "ضد المعروف، وهو ما نهى عنه الشرع لضرره وإفساده."], ["الذين تفرقوا", "أهل الكتاب من اليهود والنصارى."], ["يوم تبيضّ وجوه", "يوم القيامة."], ["ففي رحمة الله", "في الجنة."], ["نتلوها عليك بالحق", "نقرؤها عليك متلبّسة بالحق، لا باطل فيها."], ["وإلى الله تُرجع الأمور", "إليه تصير فيقضي فيها بما يشاء فضلاً وعدلاً."]], "m": "بعد أن أمر الله المؤمنين بتقواه والتمسك بدينه ونهاهم عن الفرقة، أمرهم أن تكون منهم جماعة تدعو إلى الإسلام بعرضه على الأمم والشعوب، وتأمر بالمعروف وتنهى عن المنكر في ديار الإسلام، وبشّرهم بأن الأمة التي تنهض بهذا هي المفلحة الفائزة بالنجاة من العار والنار. ثم نهاهم أن يسلكوا طريق أهل الكتاب في التفرق والاختلاف في الدين فيهلكوا هلاكهم؛ فلا ينبغي أن يكون العلم بشرائع الله سبباً في الفرقة وهو أداة الوحدة. وأخبرهم بجزاء المختلفين: عذاب عظيم يوم تبيضّ وجوه المؤمنين المؤتلفين على الكتاب والسنة، وتسودّ وجوه الكافرين المختلفين القائمين على البدع والأهواء؛ فأما الذين اسودّت وجوههم فيقال لهم توبيخاً: أكفرتم بعد إيمانكم؟ فذوقوا العذاب، وأما الذين ابيضّت وجوههم ففي رحمة الله هم فيها خالدون. ثم شرّف نبيه بخطابه: تلك آيات الله نتلوها عليك بالحق، فبلّغها، وما الله يريد ظلماً للعالمين، فلا يعذّب إلا بعد الإنذار. ولله ما في السماوات والأرض، وإليه تُرجع الأمور.", "h": ["وجوب وجود طائفة من أمة الإسلام تدعو الأمم والشعوب إلى الإسلام وتعرضه عليهم، ووجوب وجود هيئات الأمر بالمعروف والنهي عن المنكر في كل مدن المسلمين وقراهم.", "حرمة الفرقة بين المسلمين والاختلاف في دين الله.", "أهل البدع والأهواء يُعرفون في عرصات القيامة باسوداد وجوههم.", "أهل السنة والجماعة، الذين يعيشون عقيدةً وعبادةً على ما كان عليه رسول الله ﷺ وأصحابه، يُعرفون يوم العرض بابيضاض وجوههم.", "كرامة الرسول ﷺ على ربه وتقرير نبوته، وشرف من آمن به واتبعه.", "مرجع الأمور إلى الله في الدنيا والآخرة، فيجب على العقلاء أن يتخذوا عنده عهداً بالإيمان به وتوحيده."], "k": "«يدعون إلى الخير ويأمرون بالمعروف»… ما المعروف الذي أستطيع أن أدعو إليه في بيتي اليوم برفق؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (55, 3, 110, 117, 'سورة آل عمران ١١٠ – ١١٧', 'خير أمة أُخرجت للناس، وأهل الكتاب ليسوا سواء', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 55) = $j$[{"lbl": "الآيات ١١٠ – ١١٢", "q": "كُنتُمۡ خَيۡرَ أُمَّةٍ أُخۡرِجَتۡ لِلنَّاسِ تَأۡمُرُونَ بِٱلۡمَعۡرُوفِ وَتَنۡهَوۡنَ عَنِ ٱلۡمُنكَرِ وَتُؤۡمِنُونَ بِٱللَّهِۗ وَلَوۡ ءَامَنَ أَهۡلُ ٱلۡكِتَٰبِ لَكَانَ خَيۡرٗا لَّهُمۚ مِّنۡهُمُ ٱلۡمُؤۡمِنُونَ وَأَكۡثَرُهُمُ ٱلۡفَٰسِقُونَ ﴿١١٠﴾ لَن يَضُرُّوكُمۡ إِلَّآ أَذٗىۖ وَإِن يُقَٰتِلُوكُمۡ يُوَلُّوكُمُ ٱلۡأَدۡبَارَ ثُمَّ لَا يُنصَرُونَ ﴿١١١﴾ ضُرِبَتۡ عَلَيۡهِمُ ٱلذِّلَّةُ أَيۡنَ مَا ثُقِفُوٓاْ إِلَّا بِحَبۡلٖ مِّنَ ٱللَّهِ وَحَبۡلٖ مِّنَ ٱلنَّاسِ وَبَآءُو بِغَضَبٖ مِّنَ ٱللَّهِ وَضُرِبَتۡ عَلَيۡهِمُ ٱلۡمَسۡكَنَةُۚ ذَٰلِكَ بِأَنَّهُمۡ كَانُواْ يَكۡفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَيَقۡتُلُونَ ٱلۡأَنۢبِيَآءَ بِغَيۡرِ حَقّٖۚ ذَٰلِكَ بِمَا عَصَواْ وَّكَانُواْ يَعۡتَدُونَ ﴿١١٢﴾", "w": [["أُخرجت للناس", "أُظهرت وأُبرزت لهداية الناس ونفعهم."], ["أذى", "الضرر اليسير."], ["يولّوكم الأدبار", "ينهزمون فيفرّون من المعركة مولّين ظهورهم."], ["ضُربت عليهم الذلة", "أحاطت بهم المذلّة ولصقت بهم."], ["بحبل من الله وحبل من الناس", "حبل الله: الدخول في الإسلام، وحبل الناس: المعاهدة والارتباط بدولة قوية."], ["وباؤوا بغضب", "رجعوا من رحلتهم الطويلة في الكفر بغضب الله."], ["المسكنة", "ذلّة الفاقة والفقر."], ["يعتدون", "يجاوزون الحد في الظلم والشر والفساد."]], "m": "لما أمر الله المؤمنين بتقواه والاعتصام بحبله، وبتكوين جماعة تدعو إلى الخير، فامتثلوا، أثنى عليهم: «كنتم خير أمة أُخرجت للناس»، ووصفهم بما كانوا به خيرها: تأمرون بالمعروف وهو الإسلام وشرائع الهدى، وتنهون عن المنكر وهو الشرك وكبائر الإثم، وتؤمنون بالله وبكل ما أمر بالإيمان به. ثم دعا أهل الكتاب إلى الإيمان الصحيح: ولو آمنوا بمحمد ﷺ لكان خيراً لهم من دعواهم الكاذبة، ومنهم المؤمنون كعبد الله بن سلام، وأكثرهم الفاسقون. وأخبر المسلمين أن فسّاق أهل الكتاب لن يضرّوهم إلا أذى يسيراً كقول الباطل، وإن قاتلوهم ولّوهم الأدبار ثم لا يُنصرون. وأخبر أنه ضرب عليهم الذلّة أينما وُجدوا، إلا بحبل من الله وهو الإسلام، أو حبل من الناس وهو الارتباط بدولة قوية، ورجعوا بغضب من الله وضُربت عليهم المسكنة، بسبب كفرهم بآيات الله وقتلهم الأنبياء بغير حق وعصيانهم واعتدائهم.", "h": ["إثبات خيرية أمة الإسلام.", "بيان علّة خيرية أمة الإسلام: الإيمان بالله، والجهاد، والأمر بالمعروف والنهي عن المنكر.", "وعد الله لأمة الإسلام، ما تمسّكت به، بالنصر على اليهود في أي قتال يقع بينهم.", "صدق القرآن في إخباره عن اليهود بلزوم الذلة والمسكنة لهم.", "بيان جرائم اليهود التي كانت سبباً في ذلتهم: الكفر المستمر، وقتل الأنبياء بغير حق، والعصيان، والاعتداء على حدود الشرع."], "k": "خيرية هذه الأمة مشروطة بـ«تأمرون بالمعروف وتنهون عن المنكر»… فما نصيبي أنا من هذا الشرط؟"}, {"lbl": "الآيات ١١٣ – ١١٥", "q": "۞لَيۡسُواْ سَوَآءٗۗ مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ أُمَّةٞ قَآئِمَةٞ يَتۡلُونَ ءَايَٰتِ ٱللَّهِ ءَانَآءَ ٱلَّيۡلِ وَهُمۡ يَسۡجُدُونَ ﴿١١٣﴾ يُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَيَأۡمُرُونَ بِٱلۡمَعۡرُوفِ وَيَنۡهَوۡنَ عَنِ ٱلۡمُنكَرِ وَيُسَٰرِعُونَ فِي ٱلۡخَيۡرَٰتِۖ وَأُوْلَـٰٓئِكَ مِنَ ٱلصَّـٰلِحِينَ ﴿١١٤﴾ وَمَا يَفۡعَلُواْ مِنۡ خَيۡرٖ فَلَن يُكۡفَرُوهُۗ وَٱللَّهُ عَلِيمُۢ بِٱلۡمُتَّقِينَ ﴿١١٥﴾", "w": [["ليسوا سواء", "غير متساوين."], ["أمّة قائمة", "جماعة قائمة ثابتة على الإيمان والعمل الصالح."], ["يتلون آيات الله", "يقرؤون القرآن."], ["آناء الليل", "ساعات الليل."], ["فلن يُكفروه", "فلن يُجحدوه، بل يُعترف لهم به ويُجزون به وافياً."]], "m": "بعد أن ذكر الله أن أهل الكتاب فريقان، أخبر أنهم ليسوا سواء، وأثنى على أهل الصلاح منهم: منهم أمّة قائمة على الإيمان الحق، وهم الذين أسلموا، يتلون آيات الله في صلاتهم ساعات الليل وهم يسجدون، وهذا ثناء عليهم بالسجود إذ هو أعظم مظاهر الخضوع لله، ويؤمنون بالله واليوم الآخر، ويأمرون بالمعروف وينهون عن المنكر، ويبادرون إلى الخيرات قبل فواتها، وشهد لهم بالصلاح. ثم أخبر أن ما يفعلونه من خير لن يُجحد، بل يُجزون عليه أتمّ الجزاء؛ لأنهم متقون، والله عليم بالمتقين.", "h": ["فضل الثبات على الحق والقيام على الطاعات.", "فضل تلاوة القرآن الكريم في صلاة الليل.", "فضل الإيمان والدعوة إلى الإسلام.", "فضل المسابقة في الخيرات والمبادرة إلى الصالحات.", "فضيلة الكتابي إذا أسلم وحسن إسلامه، فله أجره مرتين."], "k": "«يتلون آيات الله آناء الليل وهم يسجدون»… كم آية أستطيع أن أقرأها في ركعتين قبل نومي الليلة؟"}, {"lbl": "الآيتان ١١٦ – ١١٧", "q": "إِنَّ ٱلَّذِينَ كَفَرُواْ لَن تُغۡنِيَ عَنۡهُمۡ أَمۡوَٰلُهُمۡ وَلَآ أَوۡلَٰدُهُم مِّنَ ٱللَّهِ شَيۡـٔٗاۖ وَأُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ ﴿١١٦﴾ مَثَلُ مَا يُنفِقُونَ فِي هَٰذِهِ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا كَمَثَلِ رِيحٖ فِيهَا صِرٌّ أَصَابَتۡ حَرۡثَ قَوۡمٖ ظَلَمُوٓاْ أَنفُسَهُمۡ فَأَهۡلَكَتۡهُۚ وَمَا ظَلَمَهُمُ ٱللَّهُ وَلَٰكِنۡ أَنفُسَهُمۡ يَظۡلِمُونَ ﴿١١٧﴾", "w": [["كفروا", "كذّبوا بالله ورسوله وشرعه."], ["لن تغني عنهم", "لن تجزي عنهم يوم القيامة أموالهم ولا أولادهم من عذاب الله شيئاً."], ["مثل ما ينفقون", "صفة ما ينفقونه لإبطال دعوة الإسلام أو للتصدق."], ["صِرّ", "برد شديد يقتل الزرع ويفسده."], ["الحرث", "الزرع."], ["ظلموا أنفسهم", "دنّسوها بالشرك والمعاصي فعرّضوها للهلاك."]], "m": "لما أثنى الله على مؤمني أهل الكتاب، ذكر وعيد أهل الكفر منهم ومن المشركين، على طريقة القرآن في الترغيب والترهيب: إن الذين كفروا لن تغني عنهم أموالهم ولا أولادهم من الله شيئاً، وأولئك أصحاب النار هم فيها خالدون، إذ يوم القيامة لا ينفع مال ولا بنون إلا من أتى الله بقلب سليم من الشك والشرك والكبر والعجب والنفاق. ثم ضرب مثلاً لبطلان نفقاتهم وأعمالهم التي يرونها نافعة: ريح شديدة البرد أصابت زرع قوم كاد يُحصد وهم به فرحون، فأهلكته فلم ينتفعوا بشيء منه، وما ظلمهم الله، ولكن ظلموا أنفسهم بالكفر والشرك فجزاهم بالحرمان.", "h": ["لن يغني عن المرء مال ولا ولد متى ظلم وتعرّض لنقمة الله.", "أهل الكفر هم أهل النار، وخلودهم فيها محكوم به عليهم.", "بطلان العمل الصالح بالشرك والموت على الكفر.", "استحسان ضرب الأمثال في الكلام لتقريب المعاني إلى الأذهان."], "k": "زرعٌ قارب الحصاد ثم ضاع كله… هل في أعمالي ما يُفسده عليّ رياء أو معصية دون أن أنتبه؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 55;
insert into public.tdb_cards(topic, i, body) select 55, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١١٠ – ١١٢", "q": "كُنتُمۡ خَيۡرَ أُمَّةٍ أُخۡرِجَتۡ لِلنَّاسِ تَأۡمُرُونَ بِٱلۡمَعۡرُوفِ وَتَنۡهَوۡنَ عَنِ ٱلۡمُنكَرِ وَتُؤۡمِنُونَ بِٱللَّهِۗ وَلَوۡ ءَامَنَ أَهۡلُ ٱلۡكِتَٰبِ لَكَانَ خَيۡرٗا لَّهُمۚ مِّنۡهُمُ ٱلۡمُؤۡمِنُونَ وَأَكۡثَرُهُمُ ٱلۡفَٰسِقُونَ ﴿١١٠﴾ لَن يَضُرُّوكُمۡ إِلَّآ أَذٗىۖ وَإِن يُقَٰتِلُوكُمۡ يُوَلُّوكُمُ ٱلۡأَدۡبَارَ ثُمَّ لَا يُنصَرُونَ ﴿١١١﴾ ضُرِبَتۡ عَلَيۡهِمُ ٱلذِّلَّةُ أَيۡنَ مَا ثُقِفُوٓاْ إِلَّا بِحَبۡلٖ مِّنَ ٱللَّهِ وَحَبۡلٖ مِّنَ ٱلنَّاسِ وَبَآءُو بِغَضَبٖ مِّنَ ٱللَّهِ وَضُرِبَتۡ عَلَيۡهِمُ ٱلۡمَسۡكَنَةُۚ ذَٰلِكَ بِأَنَّهُمۡ كَانُواْ يَكۡفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَيَقۡتُلُونَ ٱلۡأَنۢبِيَآءَ بِغَيۡرِ حَقّٖۚ ذَٰلِكَ بِمَا عَصَواْ وَّكَانُواْ يَعۡتَدُونَ ﴿١١٢﴾", "w": [["أُخرجت للناس", "أُظهرت وأُبرزت لهداية الناس ونفعهم."], ["أذى", "الضرر اليسير."], ["يولّوكم الأدبار", "ينهزمون فيفرّون من المعركة مولّين ظهورهم."], ["ضُربت عليهم الذلة", "أحاطت بهم المذلّة ولصقت بهم."], ["بحبل من الله وحبل من الناس", "حبل الله: الدخول في الإسلام، وحبل الناس: المعاهدة والارتباط بدولة قوية."], ["وباؤوا بغضب", "رجعوا من رحلتهم الطويلة في الكفر بغضب الله."], ["المسكنة", "ذلّة الفاقة والفقر."], ["يعتدون", "يجاوزون الحد في الظلم والشر والفساد."]], "m": "لما أمر الله المؤمنين بتقواه والاعتصام بحبله، وبتكوين جماعة تدعو إلى الخير، فامتثلوا، أثنى عليهم: «كنتم خير أمة أُخرجت للناس»، ووصفهم بما كانوا به خيرها: تأمرون بالمعروف وهو الإسلام وشرائع الهدى، وتنهون عن المنكر وهو الشرك وكبائر الإثم، وتؤمنون بالله وبكل ما أمر بالإيمان به. ثم دعا أهل الكتاب إلى الإيمان الصحيح: ولو آمنوا بمحمد ﷺ لكان خيراً لهم من دعواهم الكاذبة، ومنهم المؤمنون كعبد الله بن سلام، وأكثرهم الفاسقون. وأخبر المسلمين أن فسّاق أهل الكتاب لن يضرّوهم إلا أذى يسيراً كقول الباطل، وإن قاتلوهم ولّوهم الأدبار ثم لا يُنصرون. وأخبر أنه ضرب عليهم الذلّة أينما وُجدوا، إلا بحبل من الله وهو الإسلام، أو حبل من الناس وهو الارتباط بدولة قوية، ورجعوا بغضب من الله وضُربت عليهم المسكنة، بسبب كفرهم بآيات الله وقتلهم الأنبياء بغير حق وعصيانهم واعتدائهم.", "h": ["إثبات خيرية أمة الإسلام.", "بيان علّة خيرية أمة الإسلام: الإيمان بالله، والجهاد، والأمر بالمعروف والنهي عن المنكر.", "وعد الله لأمة الإسلام، ما تمسّكت به، بالنصر على اليهود في أي قتال يقع بينهم.", "صدق القرآن في إخباره عن اليهود بلزوم الذلة والمسكنة لهم.", "بيان جرائم اليهود التي كانت سبباً في ذلتهم: الكفر المستمر، وقتل الأنبياء بغير حق، والعصيان، والاعتداء على حدود الشرع."], "k": "خيرية هذه الأمة مشروطة بـ«تأمرون بالمعروف وتنهون عن المنكر»… فما نصيبي أنا من هذا الشرط؟"}, {"lbl": "الآيات ١١٣ – ١١٥", "q": "۞لَيۡسُواْ سَوَآءٗۗ مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ أُمَّةٞ قَآئِمَةٞ يَتۡلُونَ ءَايَٰتِ ٱللَّهِ ءَانَآءَ ٱلَّيۡلِ وَهُمۡ يَسۡجُدُونَ ﴿١١٣﴾ يُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَيَأۡمُرُونَ بِٱلۡمَعۡرُوفِ وَيَنۡهَوۡنَ عَنِ ٱلۡمُنكَرِ وَيُسَٰرِعُونَ فِي ٱلۡخَيۡرَٰتِۖ وَأُوْلَـٰٓئِكَ مِنَ ٱلصَّـٰلِحِينَ ﴿١١٤﴾ وَمَا يَفۡعَلُواْ مِنۡ خَيۡرٖ فَلَن يُكۡفَرُوهُۗ وَٱللَّهُ عَلِيمُۢ بِٱلۡمُتَّقِينَ ﴿١١٥﴾", "w": [["ليسوا سواء", "غير متساوين."], ["أمّة قائمة", "جماعة قائمة ثابتة على الإيمان والعمل الصالح."], ["يتلون آيات الله", "يقرؤون القرآن."], ["آناء الليل", "ساعات الليل."], ["فلن يُكفروه", "فلن يُجحدوه، بل يُعترف لهم به ويُجزون به وافياً."]], "m": "بعد أن ذكر الله أن أهل الكتاب فريقان، أخبر أنهم ليسوا سواء، وأثنى على أهل الصلاح منهم: منهم أمّة قائمة على الإيمان الحق، وهم الذين أسلموا، يتلون آيات الله في صلاتهم ساعات الليل وهم يسجدون، وهذا ثناء عليهم بالسجود إذ هو أعظم مظاهر الخضوع لله، ويؤمنون بالله واليوم الآخر، ويأمرون بالمعروف وينهون عن المنكر، ويبادرون إلى الخيرات قبل فواتها، وشهد لهم بالصلاح. ثم أخبر أن ما يفعلونه من خير لن يُجحد، بل يُجزون عليه أتمّ الجزاء؛ لأنهم متقون، والله عليم بالمتقين.", "h": ["فضل الثبات على الحق والقيام على الطاعات.", "فضل تلاوة القرآن الكريم في صلاة الليل.", "فضل الإيمان والدعوة إلى الإسلام.", "فضل المسابقة في الخيرات والمبادرة إلى الصالحات.", "فضيلة الكتابي إذا أسلم وحسن إسلامه، فله أجره مرتين."], "k": "«يتلون آيات الله آناء الليل وهم يسجدون»… كم آية أستطيع أن أقرأها في ركعتين قبل نومي الليلة؟"}, {"lbl": "الآيتان ١١٦ – ١١٧", "q": "إِنَّ ٱلَّذِينَ كَفَرُواْ لَن تُغۡنِيَ عَنۡهُمۡ أَمۡوَٰلُهُمۡ وَلَآ أَوۡلَٰدُهُم مِّنَ ٱللَّهِ شَيۡـٔٗاۖ وَأُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ ﴿١١٦﴾ مَثَلُ مَا يُنفِقُونَ فِي هَٰذِهِ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا كَمَثَلِ رِيحٖ فِيهَا صِرٌّ أَصَابَتۡ حَرۡثَ قَوۡمٖ ظَلَمُوٓاْ أَنفُسَهُمۡ فَأَهۡلَكَتۡهُۚ وَمَا ظَلَمَهُمُ ٱللَّهُ وَلَٰكِنۡ أَنفُسَهُمۡ يَظۡلِمُونَ ﴿١١٧﴾", "w": [["كفروا", "كذّبوا بالله ورسوله وشرعه."], ["لن تغني عنهم", "لن تجزي عنهم يوم القيامة أموالهم ولا أولادهم من عذاب الله شيئاً."], ["مثل ما ينفقون", "صفة ما ينفقونه لإبطال دعوة الإسلام أو للتصدق."], ["صِرّ", "برد شديد يقتل الزرع ويفسده."], ["الحرث", "الزرع."], ["ظلموا أنفسهم", "دنّسوها بالشرك والمعاصي فعرّضوها للهلاك."]], "m": "لما أثنى الله على مؤمني أهل الكتاب، ذكر وعيد أهل الكفر منهم ومن المشركين، على طريقة القرآن في الترغيب والترهيب: إن الذين كفروا لن تغني عنهم أموالهم ولا أولادهم من الله شيئاً، وأولئك أصحاب النار هم فيها خالدون، إذ يوم القيامة لا ينفع مال ولا بنون إلا من أتى الله بقلب سليم من الشك والشرك والكبر والعجب والنفاق. ثم ضرب مثلاً لبطلان نفقاتهم وأعمالهم التي يرونها نافعة: ريح شديدة البرد أصابت زرع قوم كاد يُحصد وهم به فرحون، فأهلكته فلم ينتفعوا بشيء منه، وما ظلمهم الله، ولكن ظلموا أنفسهم بالكفر والشرك فجزاهم بالحرمان.", "h": ["لن يغني عن المرء مال ولا ولد متى ظلم وتعرّض لنقمة الله.", "أهل الكفر هم أهل النار، وخلودهم فيها محكوم به عليهم.", "بطلان العمل الصالح بالشرك والموت على الكفر.", "استحسان ضرب الأمثال في الكلام لتقريب المعاني إلى الأذهان."], "k": "زرعٌ قارب الحصاد ثم ضاع كله… هل في أعمالي ما يُفسده عليّ رياء أو معصية دون أن أنتبه؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (56, 3, 118, 127, 'سورة آل عمران ١١٨ – ١٢٧', 'لا تتخذوا بطانة من دونكم، وتذكير بأُحد وبدر', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 56) = $j$[{"lbl": "الآيات ١١٨ – ١٢٠", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ بِطَانَةٗ مِّن دُونِكُمۡ لَا يَأۡلُونَكُمۡ خَبَالٗا وَدُّواْ مَا عَنِتُّمۡ قَدۡ بَدَتِ ٱلۡبَغۡضَآءُ مِنۡ أَفۡوَٰهِهِمۡ وَمَا تُخۡفِي صُدُورُهُمۡ أَكۡبَرُۚ قَدۡ بَيَّنَّا لَكُمُ ٱلۡأٓيَٰتِۖ إِن كُنتُمۡ تَعۡقِلُونَ ﴿١١٨﴾ هَـٰٓأَنتُمۡ أُوْلَآءِ تُحِبُّونَهُمۡ وَلَا يُحِبُّونَكُمۡ وَتُؤۡمِنُونَ بِٱلۡكِتَٰبِ كُلِّهِۦ وَإِذَا لَقُوكُمۡ قَالُوٓاْ ءَامَنَّا وَإِذَا خَلَوۡاْ عَضُّواْ عَلَيۡكُمُ ٱلۡأَنَامِلَ مِنَ ٱلۡغَيۡظِۚ قُلۡ مُوتُواْ بِغَيۡظِكُمۡۗ إِنَّ ٱللَّهَ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ ﴿١١٩﴾ إِن تَمۡسَسۡكُمۡ حَسَنَةٞ تَسُؤۡهُمۡ وَإِن تُصِبۡكُمۡ سَيِّئَةٞ يَفۡرَحُواْ بِهَاۖ وَإِن تَصۡبِرُواْ وَتَتَّقُواْ لَا يَضُرُّكُمۡ كَيۡدُهُمۡ شَيۡـًٔاۗ إِنَّ ٱللَّهَ بِمَا يَعۡمَلُونَ مُحِيطٞ ﴿١٢٠﴾", "w": [["بطانة", "بطانة الرجل: من يُطلعهم على باطن أمره الذي يخفيه عن الناس."], ["من دونكم", "من غير المسلمين كالكفار وأهل الكتاب."], ["لا يألونكم خبالاً", "لا يقصّرون في إفساد أموركم الدينية والدنيوية."], ["ودّوا ما عنتّم", "أحبّوا مشقّتكم."], ["بدت البغضاء", "ظهرت شدة بغضهم لكم."], ["بالكتاب كله", "بالكتب الإلهية كلها."], ["عضّوا عليكم الأنامل من الغيظ", "من شدة الغيظ، إذ المغتاظ يعضّ أصابعه على عادة البشر."], ["حسنة", "ما يحسن من الخير كالنصر والقوة."], ["كيدهم", "مكرهم بكم وتبييتهم الشر لكم."], ["محيط", "علماً به وقدرة عليه."]], "m": "لما أخبر الله عن مصير الكافرين، حذّر المؤمنين من موالاتهم، وخاصة الذين يحملون الغيظ والبغضاء للمسلمين، يسوؤهم أن يروهم متآلفين أقوياء، ويسرّهم أن يروهم مختلفين ضعفاء: «يا أيها الذين آمنوا لا تتخذوا بطانة من دونكم» تستشيرونهم وتُطلعونهم على أسراركم؛ لا يقصّرون في إفساد أموركم، يحبّون مشقّتكم، فلا يشيرون عليكم إلا بما يفسد عليكم أموركم، قد ظهرت البغضاء من أفواههم بما تنطق به ألسنتهم، وما تخفي صدورهم أكبر. ها أنتم تحبونهم ولا يحبونكم؛ فقد علم الله أن من المؤمنين من يحب بعض الكافرين لإحسان ظاهر بينهم، فرحمة المؤمن قد تتعدّى إلى أعدائه، وتؤمنون بالكتب كلها وهم لا يؤمنون بكتابكم، فكيف تتخذونهم بطانة؟ وإذا لقوكم قالوا آمنا، وإذا خلوا عضّوا عليكم الأنامل من الغيظ، قل موتوا بغيظكم. إن تمسسكم حسنة تسؤهم، وإن تصبكم سيئة يفرحوا بها، وإن تصبروا وتتقوا لا يضركم كيدهم شيئاً، لأن الله وليّكم، محيط بما يعملون.", "h": ["حرمة اتخاذ مستشارين وأصدقاء من أهل الكفر عامة، وحرمة إطلاعهم على أسرار الدولة الإسلامية وما يخفيه المسلمون عن أعدائهم.", "بيان رحمة المؤمنين وفضلهم على الكافرين.", "بيان نفسيات الكافرين وما يحملونه من إرادة الشر والفساد للمسلمين.", "الوقاية من كيد الكفار ومكرهم تكمن في الصبر والتجلّد وعدم إظهار الخوف لهم، مع تقوى الله."], "k": "من أستشير في أموري المهمة؟ وهل يحب لي الخير حقاً؟"}, {"lbl": "الآيات ١٢١ – ١٢٣", "q": "وَإِذۡ غَدَوۡتَ مِنۡ أَهۡلِكَ تُبَوِّئُ ٱلۡمُؤۡمِنِينَ مَقَٰعِدَ لِلۡقِتَالِۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ ﴿١٢١﴾ إِذۡ هَمَّت طَّآئِفَتَانِ مِنكُمۡ أَن تَفۡشَلَا وَٱللَّهُ وَلِيُّهُمَاۗ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ ﴿١٢٢﴾ وَلَقَدۡ نَصَرَكُمُ ٱللَّهُ بِبَدۡرٖ وَأَنتُمۡ أَذِلَّةٞۖ فَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تَشۡكُرُونَ ﴿١٢٣﴾", "w": [["وإذ غدوت", "واذكر إذ خرجت أول النهار."], ["من أهلك", "من بيتك، إذ خرج ﷺ صباح السبت من بيته إلى أُحد."], ["تبوّئ المؤمنين", "تُنزل المجاهدين الأماكن التي رأيتها صالحة من ساحة المعركة."], ["همّت", "حدّثت نفسها بالرجوع إلى المدينة."], ["طائفتان", "بنو سلمة وبنو حارثة من الأنصار."], ["أن تفشلا", "أن تضعفا وتعودا إلى ديارهما."], ["والله وليّهما", "متولّي أمرهما وناصرهما، ولذا عصمهما من ترك المسير."], ["ببدر", "بدر اسم رجل كان له ماء بذلك المكان فسُمّي به، وهو قرية على نحو مائة وخمسين كيلومتراً من المدينة."], ["وأنتم أذلّة", "لقلة عددكم وعدّتكم وتفوّق العدو عليكم."]], "m": "لما أخبر الله المؤمنين أنهم متى صبروا واتقوا لا يضرّهم كيد أعدائهم، ذكّرهم بموقفين: أحدهما لم يصبروا فيه ولم يتقوا فأصابتهم الهزيمة وهو أُحد، والثاني صبروا واتقوا فانتصروا وهو بدر. فقال: واذكر يا رسولنا إذ خرجت صباحاً من بيتك إلى أحد تُنزل المؤمنين مواقع القتال، والله سميع لما دار بينكم من القول في الخروج أو البقاء، عليم بنياتكم، ومن ذلك همّ بني سلمة وبني حارثة بالرجوع، لولا أن الله عصمهما لأنه وليّهما، فتوكّلتا عليه وواصلتا المسير. وفي أحد استُشهد من الأنصار سبعون ومن المهاجرين أربعة، وشُجّ رأس النبي ﷺ وكُسرت رباعيته واستُشهد عمه حمزة رضي الله عنه. والموقف الثاني بدر، صبر فيه المؤمنون واتقوا فنصرهم الله وهم أذلّة. ولم يقل: ولقد هزمكم بأحد وأنتم أعزة؛ لأنه كريم، فاكتفى بتذكيرهم وهم يعلمون أسباب هزيمتهم: عدم الطاعة وقلّة الصبر.", "h": ["فضيلة الصبر والتقوى، وأنهما عُدّة الجهاد في الحياة.", "استحسان التذكير بالنعم والنقم للعبرة والاتعاظ.", "ولاية الله للعبد تقيه مصارع السوء وتجنّبه الأخطار.", "تقوى الله بالعمل بأوامره واجتناب نواهيه هي الشكر الواجب على العبد."], "k": "هل في حياتي «أُحد» تعلّمتُ منها؟ وما الذي غيّرته بعدها؟"}, {"lbl": "الآيات ١٢٤ – ١٢٧", "q": "إِذۡ تَقُولُ لِلۡمُؤۡمِنِينَ أَلَن يَكۡفِيَكُمۡ أَن يُمِدَّكُمۡ رَبُّكُم بِثَلَٰثَةِ ءَالَٰفٖ مِّنَ ٱلۡمَلَـٰٓئِكَةِ مُنزَلِينَ ﴿١٢٤﴾ بَلَىٰٓۚ إِن تَصۡبِرُواْ وَتَتَّقُواْ وَيَأۡتُوكُم مِّن فَوۡرِهِمۡ هَٰذَا يُمۡدِدۡكُمۡ رَبُّكُم بِخَمۡسَةِ ءَالَٰفٖ مِّنَ ٱلۡمَلَـٰٓئِكَةِ مُسَوِّمِينَ ﴿١٢٥﴾ وَمَا جَعَلَهُ ٱللَّهُ إِلَّا بُشۡرَىٰ لَكُمۡ وَلِتَطۡمَئِنَّ قُلُوبُكُم بِهِۦۗ وَمَا ٱلنَّصۡرُ إِلَّا مِنۡ عِندِ ٱللَّهِ ٱلۡعَزِيزِ ٱلۡحَكِيمِ ﴿١٢٦﴾ لِيَقۡطَعَ طَرَفٗا مِّنَ ٱلَّذِينَ كَفَرُوٓاْ أَوۡ يَكۡبِتَهُمۡ فَيَنقَلِبُواْ خَآئِبِينَ ﴿١٢٧﴾", "w": [["أن يمدّكم", "بالملائكة عوناً لكم على قتال أعدائكم المتفوقين عليكم."], ["الملائكة", "عباد لله مكرمون مخلوقون من نور، لا يعصون الله ما أمرهم."], ["بلى", "حرف إجابة، أي يكفيكم."], ["من فورهم هذا", "من وجههم في وقتهم هذا."], ["مسوّمين", "معلَّمين بعلامات تعرفونهم بها."], ["إلا بشرى لكم", "البشرى: الخبر السار الذي يتهلّل له الوجه."], ["ولتطمئن به قلوبكم", "تسكن ويذهب عنها الخوف والقلق."], ["ليقطع طرفاً", "ليهلك من جيش العدو طائفة."], ["أو يكبتهم", "يخزيهم ويذلّهم."], ["فينقلبوا خائبين", "يرجعوا إلى ديارهم خائبين لم يحرزوا النصر الذي أمّلوه."]], "m": "ما زال السياق في تذكير الرسول ﷺ والمؤمنين بما تمّ لهم من النصر في بدر لما صبروا واتقوا: إذ تقول للمؤمنين لما بلغهم أن كُرز بن جابر يريد أن يمدّ المشركين برجاله فشقّ ذلك عليهم: ألن يكفيكم أن يمدّكم ربكم بثلاثة آلاف من الملائكة منزلين؟ بلى، إن تصبروا وتتقوا ويأتوكم من فورهم هذا يمددكم ربكم بخمسة آلاف من الملائكة مسوّمين. ولما انهزم كرز وقعد عن إمداد قريش لم يمدّهم الله بها، واكتفى بالألف التي أمدّهم بها لما استغاثوه أول المعركة، كما في سورة الأنفال. وما جعل الله هذا الإمداد إلا بشرى لكم ولتطمئن به قلوبكم، وما النصر إلا من عند الله العزيز الحكيم، يضعه في أهل الصبر والتقوى، ليهلك طائفة من الذين كفروا، وقد أهلك منهم سبعين، أو يخزيهم إذ أُسر منهم سبعون، فينقلبوا خائبين.", "h": ["بيان سبب هزيمة المسلمين في أحد، وهو عدم صبرهم وإخلالهم بالتقوى؛ إذ عصى الرماة أمر رسول الله ﷺ ونزلوا من الجبل وراء الغنيمة، على تفسير أن الوعد بالثلاثة آلاف والخمسة كان بأحد مشروطاً بالصبر والتقوى.", "النصر وإن كانت له عوامله من كثرة العدد وقوة العدة فإنه بيد الله، فقد ينصر الضعيف ويخذل القوي؛ فوجب تحقيق ولاية الله أولاً بالإيمان والصبر والطاعة ثم التوكل عليه.", "ثبوت قتال الملائكة مع أصحاب رسول الله ﷺ في بدر قتالاً حقيقياً."], "k": "«وما النصر إلا من عند الله»… في معركتي اليوم مع نفسي أو مع ظروفي، هل أعتمد على قوتي أم على ربي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 56;
insert into public.tdb_cards(topic, i, body) select 56, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١١٨ – ١٢٠", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ بِطَانَةٗ مِّن دُونِكُمۡ لَا يَأۡلُونَكُمۡ خَبَالٗا وَدُّواْ مَا عَنِتُّمۡ قَدۡ بَدَتِ ٱلۡبَغۡضَآءُ مِنۡ أَفۡوَٰهِهِمۡ وَمَا تُخۡفِي صُدُورُهُمۡ أَكۡبَرُۚ قَدۡ بَيَّنَّا لَكُمُ ٱلۡأٓيَٰتِۖ إِن كُنتُمۡ تَعۡقِلُونَ ﴿١١٨﴾ هَـٰٓأَنتُمۡ أُوْلَآءِ تُحِبُّونَهُمۡ وَلَا يُحِبُّونَكُمۡ وَتُؤۡمِنُونَ بِٱلۡكِتَٰبِ كُلِّهِۦ وَإِذَا لَقُوكُمۡ قَالُوٓاْ ءَامَنَّا وَإِذَا خَلَوۡاْ عَضُّواْ عَلَيۡكُمُ ٱلۡأَنَامِلَ مِنَ ٱلۡغَيۡظِۚ قُلۡ مُوتُواْ بِغَيۡظِكُمۡۗ إِنَّ ٱللَّهَ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ ﴿١١٩﴾ إِن تَمۡسَسۡكُمۡ حَسَنَةٞ تَسُؤۡهُمۡ وَإِن تُصِبۡكُمۡ سَيِّئَةٞ يَفۡرَحُواْ بِهَاۖ وَإِن تَصۡبِرُواْ وَتَتَّقُواْ لَا يَضُرُّكُمۡ كَيۡدُهُمۡ شَيۡـًٔاۗ إِنَّ ٱللَّهَ بِمَا يَعۡمَلُونَ مُحِيطٞ ﴿١٢٠﴾", "w": [["بطانة", "بطانة الرجل: من يُطلعهم على باطن أمره الذي يخفيه عن الناس."], ["من دونكم", "من غير المسلمين كالكفار وأهل الكتاب."], ["لا يألونكم خبالاً", "لا يقصّرون في إفساد أموركم الدينية والدنيوية."], ["ودّوا ما عنتّم", "أحبّوا مشقّتكم."], ["بدت البغضاء", "ظهرت شدة بغضهم لكم."], ["بالكتاب كله", "بالكتب الإلهية كلها."], ["عضّوا عليكم الأنامل من الغيظ", "من شدة الغيظ، إذ المغتاظ يعضّ أصابعه على عادة البشر."], ["حسنة", "ما يحسن من الخير كالنصر والقوة."], ["كيدهم", "مكرهم بكم وتبييتهم الشر لكم."], ["محيط", "علماً به وقدرة عليه."]], "m": "لما أخبر الله عن مصير الكافرين، حذّر المؤمنين من موالاتهم، وخاصة الذين يحملون الغيظ والبغضاء للمسلمين، يسوؤهم أن يروهم متآلفين أقوياء، ويسرّهم أن يروهم مختلفين ضعفاء: «يا أيها الذين آمنوا لا تتخذوا بطانة من دونكم» تستشيرونهم وتُطلعونهم على أسراركم؛ لا يقصّرون في إفساد أموركم، يحبّون مشقّتكم، فلا يشيرون عليكم إلا بما يفسد عليكم أموركم، قد ظهرت البغضاء من أفواههم بما تنطق به ألسنتهم، وما تخفي صدورهم أكبر. ها أنتم تحبونهم ولا يحبونكم؛ فقد علم الله أن من المؤمنين من يحب بعض الكافرين لإحسان ظاهر بينهم، فرحمة المؤمن قد تتعدّى إلى أعدائه، وتؤمنون بالكتب كلها وهم لا يؤمنون بكتابكم، فكيف تتخذونهم بطانة؟ وإذا لقوكم قالوا آمنا، وإذا خلوا عضّوا عليكم الأنامل من الغيظ، قل موتوا بغيظكم. إن تمسسكم حسنة تسؤهم، وإن تصبكم سيئة يفرحوا بها، وإن تصبروا وتتقوا لا يضركم كيدهم شيئاً، لأن الله وليّكم، محيط بما يعملون.", "h": ["حرمة اتخاذ مستشارين وأصدقاء من أهل الكفر عامة، وحرمة إطلاعهم على أسرار الدولة الإسلامية وما يخفيه المسلمون عن أعدائهم.", "بيان رحمة المؤمنين وفضلهم على الكافرين.", "بيان نفسيات الكافرين وما يحملونه من إرادة الشر والفساد للمسلمين.", "الوقاية من كيد الكفار ومكرهم تكمن في الصبر والتجلّد وعدم إظهار الخوف لهم، مع تقوى الله."], "k": "من أستشير في أموري المهمة؟ وهل يحب لي الخير حقاً؟"}, {"lbl": "الآيات ١٢١ – ١٢٣", "q": "وَإِذۡ غَدَوۡتَ مِنۡ أَهۡلِكَ تُبَوِّئُ ٱلۡمُؤۡمِنِينَ مَقَٰعِدَ لِلۡقِتَالِۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ ﴿١٢١﴾ إِذۡ هَمَّت طَّآئِفَتَانِ مِنكُمۡ أَن تَفۡشَلَا وَٱللَّهُ وَلِيُّهُمَاۗ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ ﴿١٢٢﴾ وَلَقَدۡ نَصَرَكُمُ ٱللَّهُ بِبَدۡرٖ وَأَنتُمۡ أَذِلَّةٞۖ فَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تَشۡكُرُونَ ﴿١٢٣﴾", "w": [["وإذ غدوت", "واذكر إذ خرجت أول النهار."], ["من أهلك", "من بيتك، إذ خرج ﷺ صباح السبت من بيته إلى أُحد."], ["تبوّئ المؤمنين", "تُنزل المجاهدين الأماكن التي رأيتها صالحة من ساحة المعركة."], ["همّت", "حدّثت نفسها بالرجوع إلى المدينة."], ["طائفتان", "بنو سلمة وبنو حارثة من الأنصار."], ["أن تفشلا", "أن تضعفا وتعودا إلى ديارهما."], ["والله وليّهما", "متولّي أمرهما وناصرهما، ولذا عصمهما من ترك المسير."], ["ببدر", "بدر اسم رجل كان له ماء بذلك المكان فسُمّي به، وهو قرية على نحو مائة وخمسين كيلومتراً من المدينة."], ["وأنتم أذلّة", "لقلة عددكم وعدّتكم وتفوّق العدو عليكم."]], "m": "لما أخبر الله المؤمنين أنهم متى صبروا واتقوا لا يضرّهم كيد أعدائهم، ذكّرهم بموقفين: أحدهما لم يصبروا فيه ولم يتقوا فأصابتهم الهزيمة وهو أُحد، والثاني صبروا واتقوا فانتصروا وهو بدر. فقال: واذكر يا رسولنا إذ خرجت صباحاً من بيتك إلى أحد تُنزل المؤمنين مواقع القتال، والله سميع لما دار بينكم من القول في الخروج أو البقاء، عليم بنياتكم، ومن ذلك همّ بني سلمة وبني حارثة بالرجوع، لولا أن الله عصمهما لأنه وليّهما، فتوكّلتا عليه وواصلتا المسير. وفي أحد استُشهد من الأنصار سبعون ومن المهاجرين أربعة، وشُجّ رأس النبي ﷺ وكُسرت رباعيته واستُشهد عمه حمزة رضي الله عنه. والموقف الثاني بدر، صبر فيه المؤمنون واتقوا فنصرهم الله وهم أذلّة. ولم يقل: ولقد هزمكم بأحد وأنتم أعزة؛ لأنه كريم، فاكتفى بتذكيرهم وهم يعلمون أسباب هزيمتهم: عدم الطاعة وقلّة الصبر.", "h": ["فضيلة الصبر والتقوى، وأنهما عُدّة الجهاد في الحياة.", "استحسان التذكير بالنعم والنقم للعبرة والاتعاظ.", "ولاية الله للعبد تقيه مصارع السوء وتجنّبه الأخطار.", "تقوى الله بالعمل بأوامره واجتناب نواهيه هي الشكر الواجب على العبد."], "k": "هل في حياتي «أُحد» تعلّمتُ منها؟ وما الذي غيّرته بعدها؟"}, {"lbl": "الآيات ١٢٤ – ١٢٧", "q": "إِذۡ تَقُولُ لِلۡمُؤۡمِنِينَ أَلَن يَكۡفِيَكُمۡ أَن يُمِدَّكُمۡ رَبُّكُم بِثَلَٰثَةِ ءَالَٰفٖ مِّنَ ٱلۡمَلَـٰٓئِكَةِ مُنزَلِينَ ﴿١٢٤﴾ بَلَىٰٓۚ إِن تَصۡبِرُواْ وَتَتَّقُواْ وَيَأۡتُوكُم مِّن فَوۡرِهِمۡ هَٰذَا يُمۡدِدۡكُمۡ رَبُّكُم بِخَمۡسَةِ ءَالَٰفٖ مِّنَ ٱلۡمَلَـٰٓئِكَةِ مُسَوِّمِينَ ﴿١٢٥﴾ وَمَا جَعَلَهُ ٱللَّهُ إِلَّا بُشۡرَىٰ لَكُمۡ وَلِتَطۡمَئِنَّ قُلُوبُكُم بِهِۦۗ وَمَا ٱلنَّصۡرُ إِلَّا مِنۡ عِندِ ٱللَّهِ ٱلۡعَزِيزِ ٱلۡحَكِيمِ ﴿١٢٦﴾ لِيَقۡطَعَ طَرَفٗا مِّنَ ٱلَّذِينَ كَفَرُوٓاْ أَوۡ يَكۡبِتَهُمۡ فَيَنقَلِبُواْ خَآئِبِينَ ﴿١٢٧﴾", "w": [["أن يمدّكم", "بالملائكة عوناً لكم على قتال أعدائكم المتفوقين عليكم."], ["الملائكة", "عباد لله مكرمون مخلوقون من نور، لا يعصون الله ما أمرهم."], ["بلى", "حرف إجابة، أي يكفيكم."], ["من فورهم هذا", "من وجههم في وقتهم هذا."], ["مسوّمين", "معلَّمين بعلامات تعرفونهم بها."], ["إلا بشرى لكم", "البشرى: الخبر السار الذي يتهلّل له الوجه."], ["ولتطمئن به قلوبكم", "تسكن ويذهب عنها الخوف والقلق."], ["ليقطع طرفاً", "ليهلك من جيش العدو طائفة."], ["أو يكبتهم", "يخزيهم ويذلّهم."], ["فينقلبوا خائبين", "يرجعوا إلى ديارهم خائبين لم يحرزوا النصر الذي أمّلوه."]], "m": "ما زال السياق في تذكير الرسول ﷺ والمؤمنين بما تمّ لهم من النصر في بدر لما صبروا واتقوا: إذ تقول للمؤمنين لما بلغهم أن كُرز بن جابر يريد أن يمدّ المشركين برجاله فشقّ ذلك عليهم: ألن يكفيكم أن يمدّكم ربكم بثلاثة آلاف من الملائكة منزلين؟ بلى، إن تصبروا وتتقوا ويأتوكم من فورهم هذا يمددكم ربكم بخمسة آلاف من الملائكة مسوّمين. ولما انهزم كرز وقعد عن إمداد قريش لم يمدّهم الله بها، واكتفى بالألف التي أمدّهم بها لما استغاثوه أول المعركة، كما في سورة الأنفال. وما جعل الله هذا الإمداد إلا بشرى لكم ولتطمئن به قلوبكم، وما النصر إلا من عند الله العزيز الحكيم، يضعه في أهل الصبر والتقوى، ليهلك طائفة من الذين كفروا، وقد أهلك منهم سبعين، أو يخزيهم إذ أُسر منهم سبعون، فينقلبوا خائبين.", "h": ["بيان سبب هزيمة المسلمين في أحد، وهو عدم صبرهم وإخلالهم بالتقوى؛ إذ عصى الرماة أمر رسول الله ﷺ ونزلوا من الجبل وراء الغنيمة، على تفسير أن الوعد بالثلاثة آلاف والخمسة كان بأحد مشروطاً بالصبر والتقوى.", "النصر وإن كانت له عوامله من كثرة العدد وقوة العدة فإنه بيد الله، فقد ينصر الضعيف ويخذل القوي؛ فوجب تحقيق ولاية الله أولاً بالإيمان والصبر والطاعة ثم التوكل عليه.", "ثبوت قتال الملائكة مع أصحاب رسول الله ﷺ في بدر قتالاً حقيقياً."], "k": "«وما النصر إلا من عند الله»… في معركتي اليوم مع نفسي أو مع ظروفي، هل أعتمد على قوتي أم على ربي؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (57, 3, 128, 136, 'سورة آل عمران ١٢٨ – ١٣٦', 'ليس لك من الأمر شيء، وتحريم الربا، والمسارعة إلى المغفرة', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 57) = $j$[{"lbl": "الآيات ١٢٨ – ١٣٢", "q": "لَيۡسَ لَكَ مِنَ ٱلۡأَمۡرِ شَيۡءٌ أَوۡ يَتُوبَ عَلَيۡهِمۡ أَوۡ يُعَذِّبَهُمۡ فَإِنَّهُمۡ ظَٰلِمُونَ ﴿١٢٨﴾ وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ يَغۡفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ ﴿١٢٩﴾ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَأۡكُلُواْ ٱلرِّبَوٰٓاْ أَضۡعَٰفٗا مُّضَٰعَفَةٗۖ وَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تُفۡلِحُونَ ﴿١٣٠﴾ وَٱتَّقُواْ ٱلنَّارَ ٱلَّتِيٓ أُعِدَّتۡ لِلۡكَٰفِرِينَ ﴿١٣١﴾ وَأَطِيعُواْ ٱللَّهَ وَٱلرَّسُولَ لَعَلَّكُمۡ تُرۡحَمُونَ ﴿١٣٢﴾", "w": [["الأمر", "الشأن، والمراد هنا توبة الله على الكافرين أو تعذيبهم."], ["أو يتوب عليهم", "«أو» هنا بمعنى حتى، أي: فاصبر حتى يتوب عليهم أو يعذبهم."], ["له ما في السموات", "ملكاً وخلقاً وعبيداً، يتصرف كيف يشاء ويحكم كما يريد."], ["لا تأكلوا الربا", "لا مفهوم للأكل، بل كل تصرف بالربا حرام."], ["الربا", "لغةً: الزيادة، وفي الشرع نوعان: ربا الفضل، وهو الزيادة عند بيع الجنس بمثله من الذهب والفضة والبُرّ والشعير والتمر والملح، وربا النسيئة، وهو أن يحلّ أجل الدين فلا يجد المدين سداداً فيقول: أخّرني وزد في الدين."], ["أضعافاً مضاعفة", "لا مفهوم له؛ إذ الدرهم الواحد حرام كالألف، وإنما كانوا في الجاهلية يؤخّرون الدين ويزيدون حتى يتضاعف."], ["تفلحون", "تنجون من العذاب وتظفرون بالنعيم المقيم في الجنة."], ["أُعدّت للكافرين", "هُيّئت وأُحضرت للمكذبين لله ورسوله ﷺ."], ["لعلكم ترحمون", "لتُرحموا فلا تُعذَّبوا بما صدر منكم من ذنب."]], "m": "صحّ أن النبي ﷺ كان قد دعا على أفراد من المشركين بالعذاب، وقال يوم أحد لما شُجّ رأسه وكُسرت رباعيته: «كيف يفلح قوم فعلوا هذا بنبيهم؟» فأنزل الله: «ليس لك من الأمر شيء»، أي فاصبر حتى يتوب الله عليهم أو يعذبهم فإنهم ظالمون، ولله ما في السموات وما في الأرض، إن عذّب فبعدله، وإن رحم فبفضله، وهو الغفور لمن تاب، الرحيم بمن أناب. ثم نادى المؤمنين بعد أن خرجوا من الجاهلية أن يتركوا الربا وكل تعامل به؛ إذ كان الرجل يحلّ أجل دينه فلا يجد ما يسدد به، فيقول لدائنه: أخّرني وزد عليّ، وهكذا مرة بعد مرة حتى يصير الدين بعد عشرة عشرين وثلاثين، ثم أمرهم بتقواه ووعدهم بالفلاح. وأمرهم باتقاء النار التي أُعدّت للكافرين، ويكون اتقاؤها بطاعته وطاعة رسوله ﷺ، ثم أمرهم بطاعته وطاعة رسوله ووعدهم بالرحمة، وكأنه يشير إلى الرماة الذين عصوا رسول الله ﷺ في أحد فتخلّوا عن مواقعهم فتسبّبوا في الهزيمة.", "h": ["استقلال الرب تعالى بالأمر كله، فليس لأحد من خلقه تصرف في شيء إلا ما أذن فيه للعبد.", "الظلم مستوجب للعذاب ما لم يتدارك الربُّ العبدَ بتوبة فيتوب عليه ويغفر له.", "حرمة أكل الربا مطلقاً، مضاعفاً كان أو غير مضاعف.", "بيان ربا الجاهلية، وهو الذي نهى الله عنه بقوله: «لا تأكلوا الربا».", "وجوب التقوى لمن أراد الفلاح في الدنيا والآخرة.", "وجوب اتقاء النار ولو بشق تمرة.", "وجوب طاعة الله ورسوله للحصول على الرحمة الإلهية، وهي العفو والمغفرة ودخول الجنة."], "k": "«ليس لك من الأمر شيء»… قالها الله لنبيه ﷺ، فهل أسلّم أنا لله في أمورٍ لا أملكها؟"}, {"lbl": "الآيات ١٣٣ – ١٣٦", "q": "۞وَسَارِعُوٓاْ إِلَىٰ مَغۡفِرَةٖ مِّن رَّبِّكُمۡ وَجَنَّةٍ عَرۡضُهَا ٱلسَّمَٰوَٰتُ وَٱلۡأَرۡضُ أُعِدَّتۡ لِلۡمُتَّقِينَ ﴿١٣٣﴾ ٱلَّذِينَ يُنفِقُونَ فِي ٱلسَّرَّآءِ وَٱلضَّرَّآءِ وَٱلۡكَٰظِمِينَ ٱلۡغَيۡظَ وَٱلۡعَافِينَ عَنِ ٱلنَّاسِۗ وَٱللَّهُ يُحِبُّ ٱلۡمُحۡسِنِينَ ﴿١٣٤﴾ وَٱلَّذِينَ إِذَا فَعَلُواْ فَٰحِشَةً أَوۡ ظَلَمُوٓاْ أَنفُسَهُمۡ ذَكَرُواْ ٱللَّهَ فَٱسۡتَغۡفَرُواْ لِذُنُوبِهِمۡ وَمَن يَغۡفِرُ ٱلذُّنُوبَ إِلَّا ٱللَّهُ وَلَمۡ يُصِرُّواْ عَلَىٰ مَا فَعَلُواْ وَهُمۡ يَعۡلَمُونَ ﴿١٣٥﴾ أُوْلَـٰٓئِكَ جَزَآؤُهُم مَّغۡفِرَةٞ مِّن رَّبِّهِمۡ وَجَنَّـٰتٞ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ وَنِعۡمَ أَجۡرُ ٱلۡعَٰمِلِينَ ﴿١٣٦﴾", "w": [["وسارعوا", "بادروا دون توانٍ ولا تراخٍ."], ["إلى مغفرة", "المغفرة: ستر الذنوب وعدم المؤاخذة بها، والمسارعة إليها بالتوبة وترك الذنوب وكثرة الاستغفار."], ["وجنة", "الجنة دار النعيم فوق السموات، والمسارعة إليها بالإكثار من الصالحات."], ["أُعدّت", "هُيّئت وأُحضرت، فهي موجودة الآن مهيّأة."], ["للمتقين", "الذين اتقوا الله فلم يعصوه بترك واجب ولا فعل محرم، وإن حدث منهم ذنب تابوا منه فوراً."], ["في السراء والضراء", "في حال اليسر والغنى، وحال الفقر."], ["والكاظمين الغيظ", "كظم الغيظ: حبسه وعدم إظهاره على الجوارح بسبٍّ أو ضرب ونحوهما للتشفّي والانتقام."], ["والعافين عن الناس", "العفو: عدم مؤاخذة المسيء مع القدرة على ذلك."], ["المحسنين", "الذين يبرّون ولا يسيئون في قول أو عمل."], ["فاحشة", "الفعلة الشديدة القبح كالزنى وكبائر الذنوب."], ["ظلموا أنفسهم", "بترك واجب أو فعل محرم فدنّسوها بذلك."], ["ولم يصرّوا", "لم يقيموا على الذنب، بل يسارعون إلى التوبة."], ["ونعم أجر العاملين", "الجنة."]], "m": "لما نهى الله المؤمنين عن الربا وأمرهم بتقواه واتقاء النار وطاعته وطاعة رسوله، أمرهم بالمسارعة إلى شيئين: مغفرة ذنوبهم بالتوبة النصوح، وجنة عرضها السموات والأرض أُعدّت للمتقين، والمسارعة إليها مسارعة إلى موجبات دخولها: الإيمان والعمل الصالح، إذ بهما تزكو الروح فتكون أهلاً للجنة. ثم وصف المتقين: ينفقون في كل أحوالهم، في الغنى والفقر والعسر واليسر، ويكظمون الغيظ حلماً وكرماً، ويعفون عن زلات الناس، وهذا إحسان ظاهر، ولذا بشّرهم بحبه: «والله يحب المحسنين». ومن صفاتهم ملازمة ذكر الله وعدم الغفلة، فإذا فعلوا فاحشة أو ظلموا أنفسهم بذنب دونها ذكروا وعيد الله ونهيه، فبادروا إلى التوبة: الإقلاع عن الذنب، والندم، والعزم على عدم العودة، واستغفار الله منه، ولم يواظبوا على الذنب وهم يعلمون أنه ذنب. وجزاؤهم مغفرة ذنوبهم كلها، والخلود في الجنة ذات النعيم المقيم، ونعم أجر العاملين.", "h": ["وجوب تعجيل التوبة وعدم التسويف فيها، لقوله: «سارعوا».", "سعة الجنة، وأنها مخلوقة الآن، لقوله: «أُعدّت».", "المتقون هم أهل الجنة وورثتها بحق.", "فضل استمرار الإنفاق في سبيل الله ولو بالقليل.", "فضيلة كظم الغيظ بترك المبادرة إلى التشفي والانتقام.", "فضل العفو عن الناس مطلقاً: مؤمنهم وكافرهم، بارّهم وفاجرهم.", "فضيلة الاستغفار وترك الإصرار على المعصية، للآية ولحديث: «ما أصرّ من استغفر ولو عاد في اليوم سبعين مرة»."], "k": "آخر مرة غضبت فيها… هل كظمتُ غيظي؟ ومن أحتاج أن أعفو عنه اليوم؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 57;
insert into public.tdb_cards(topic, i, body) select 57, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٢٨ – ١٣٢", "q": "لَيۡسَ لَكَ مِنَ ٱلۡأَمۡرِ شَيۡءٌ أَوۡ يَتُوبَ عَلَيۡهِمۡ أَوۡ يُعَذِّبَهُمۡ فَإِنَّهُمۡ ظَٰلِمُونَ ﴿١٢٨﴾ وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ يَغۡفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ ﴿١٢٩﴾ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَأۡكُلُواْ ٱلرِّبَوٰٓاْ أَضۡعَٰفٗا مُّضَٰعَفَةٗۖ وَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تُفۡلِحُونَ ﴿١٣٠﴾ وَٱتَّقُواْ ٱلنَّارَ ٱلَّتِيٓ أُعِدَّتۡ لِلۡكَٰفِرِينَ ﴿١٣١﴾ وَأَطِيعُواْ ٱللَّهَ وَٱلرَّسُولَ لَعَلَّكُمۡ تُرۡحَمُونَ ﴿١٣٢﴾", "w": [["الأمر", "الشأن، والمراد هنا توبة الله على الكافرين أو تعذيبهم."], ["أو يتوب عليهم", "«أو» هنا بمعنى حتى، أي: فاصبر حتى يتوب عليهم أو يعذبهم."], ["له ما في السموات", "ملكاً وخلقاً وعبيداً، يتصرف كيف يشاء ويحكم كما يريد."], ["لا تأكلوا الربا", "لا مفهوم للأكل، بل كل تصرف بالربا حرام."], ["الربا", "لغةً: الزيادة، وفي الشرع نوعان: ربا الفضل، وهو الزيادة عند بيع الجنس بمثله من الذهب والفضة والبُرّ والشعير والتمر والملح، وربا النسيئة، وهو أن يحلّ أجل الدين فلا يجد المدين سداداً فيقول: أخّرني وزد في الدين."], ["أضعافاً مضاعفة", "لا مفهوم له؛ إذ الدرهم الواحد حرام كالألف، وإنما كانوا في الجاهلية يؤخّرون الدين ويزيدون حتى يتضاعف."], ["تفلحون", "تنجون من العذاب وتظفرون بالنعيم المقيم في الجنة."], ["أُعدّت للكافرين", "هُيّئت وأُحضرت للمكذبين لله ورسوله ﷺ."], ["لعلكم ترحمون", "لتُرحموا فلا تُعذَّبوا بما صدر منكم من ذنب."]], "m": "صحّ أن النبي ﷺ كان قد دعا على أفراد من المشركين بالعذاب، وقال يوم أحد لما شُجّ رأسه وكُسرت رباعيته: «كيف يفلح قوم فعلوا هذا بنبيهم؟» فأنزل الله: «ليس لك من الأمر شيء»، أي فاصبر حتى يتوب الله عليهم أو يعذبهم فإنهم ظالمون، ولله ما في السموات وما في الأرض، إن عذّب فبعدله، وإن رحم فبفضله، وهو الغفور لمن تاب، الرحيم بمن أناب. ثم نادى المؤمنين بعد أن خرجوا من الجاهلية أن يتركوا الربا وكل تعامل به؛ إذ كان الرجل يحلّ أجل دينه فلا يجد ما يسدد به، فيقول لدائنه: أخّرني وزد عليّ، وهكذا مرة بعد مرة حتى يصير الدين بعد عشرة عشرين وثلاثين، ثم أمرهم بتقواه ووعدهم بالفلاح. وأمرهم باتقاء النار التي أُعدّت للكافرين، ويكون اتقاؤها بطاعته وطاعة رسوله ﷺ، ثم أمرهم بطاعته وطاعة رسوله ووعدهم بالرحمة، وكأنه يشير إلى الرماة الذين عصوا رسول الله ﷺ في أحد فتخلّوا عن مواقعهم فتسبّبوا في الهزيمة.", "h": ["استقلال الرب تعالى بالأمر كله، فليس لأحد من خلقه تصرف في شيء إلا ما أذن فيه للعبد.", "الظلم مستوجب للعذاب ما لم يتدارك الربُّ العبدَ بتوبة فيتوب عليه ويغفر له.", "حرمة أكل الربا مطلقاً، مضاعفاً كان أو غير مضاعف.", "بيان ربا الجاهلية، وهو الذي نهى الله عنه بقوله: «لا تأكلوا الربا».", "وجوب التقوى لمن أراد الفلاح في الدنيا والآخرة.", "وجوب اتقاء النار ولو بشق تمرة.", "وجوب طاعة الله ورسوله للحصول على الرحمة الإلهية، وهي العفو والمغفرة ودخول الجنة."], "k": "«ليس لك من الأمر شيء»… قالها الله لنبيه ﷺ، فهل أسلّم أنا لله في أمورٍ لا أملكها؟"}, {"lbl": "الآيات ١٣٣ – ١٣٦", "q": "۞وَسَارِعُوٓاْ إِلَىٰ مَغۡفِرَةٖ مِّن رَّبِّكُمۡ وَجَنَّةٍ عَرۡضُهَا ٱلسَّمَٰوَٰتُ وَٱلۡأَرۡضُ أُعِدَّتۡ لِلۡمُتَّقِينَ ﴿١٣٣﴾ ٱلَّذِينَ يُنفِقُونَ فِي ٱلسَّرَّآءِ وَٱلضَّرَّآءِ وَٱلۡكَٰظِمِينَ ٱلۡغَيۡظَ وَٱلۡعَافِينَ عَنِ ٱلنَّاسِۗ وَٱللَّهُ يُحِبُّ ٱلۡمُحۡسِنِينَ ﴿١٣٤﴾ وَٱلَّذِينَ إِذَا فَعَلُواْ فَٰحِشَةً أَوۡ ظَلَمُوٓاْ أَنفُسَهُمۡ ذَكَرُواْ ٱللَّهَ فَٱسۡتَغۡفَرُواْ لِذُنُوبِهِمۡ وَمَن يَغۡفِرُ ٱلذُّنُوبَ إِلَّا ٱللَّهُ وَلَمۡ يُصِرُّواْ عَلَىٰ مَا فَعَلُواْ وَهُمۡ يَعۡلَمُونَ ﴿١٣٥﴾ أُوْلَـٰٓئِكَ جَزَآؤُهُم مَّغۡفِرَةٞ مِّن رَّبِّهِمۡ وَجَنَّـٰتٞ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ وَنِعۡمَ أَجۡرُ ٱلۡعَٰمِلِينَ ﴿١٣٦﴾", "w": [["وسارعوا", "بادروا دون توانٍ ولا تراخٍ."], ["إلى مغفرة", "المغفرة: ستر الذنوب وعدم المؤاخذة بها، والمسارعة إليها بالتوبة وترك الذنوب وكثرة الاستغفار."], ["وجنة", "الجنة دار النعيم فوق السموات، والمسارعة إليها بالإكثار من الصالحات."], ["أُعدّت", "هُيّئت وأُحضرت، فهي موجودة الآن مهيّأة."], ["للمتقين", "الذين اتقوا الله فلم يعصوه بترك واجب ولا فعل محرم، وإن حدث منهم ذنب تابوا منه فوراً."], ["في السراء والضراء", "في حال اليسر والغنى، وحال الفقر."], ["والكاظمين الغيظ", "كظم الغيظ: حبسه وعدم إظهاره على الجوارح بسبٍّ أو ضرب ونحوهما للتشفّي والانتقام."], ["والعافين عن الناس", "العفو: عدم مؤاخذة المسيء مع القدرة على ذلك."], ["المحسنين", "الذين يبرّون ولا يسيئون في قول أو عمل."], ["فاحشة", "الفعلة الشديدة القبح كالزنى وكبائر الذنوب."], ["ظلموا أنفسهم", "بترك واجب أو فعل محرم فدنّسوها بذلك."], ["ولم يصرّوا", "لم يقيموا على الذنب، بل يسارعون إلى التوبة."], ["ونعم أجر العاملين", "الجنة."]], "m": "لما نهى الله المؤمنين عن الربا وأمرهم بتقواه واتقاء النار وطاعته وطاعة رسوله، أمرهم بالمسارعة إلى شيئين: مغفرة ذنوبهم بالتوبة النصوح، وجنة عرضها السموات والأرض أُعدّت للمتقين، والمسارعة إليها مسارعة إلى موجبات دخولها: الإيمان والعمل الصالح، إذ بهما تزكو الروح فتكون أهلاً للجنة. ثم وصف المتقين: ينفقون في كل أحوالهم، في الغنى والفقر والعسر واليسر، ويكظمون الغيظ حلماً وكرماً، ويعفون عن زلات الناس، وهذا إحسان ظاهر، ولذا بشّرهم بحبه: «والله يحب المحسنين». ومن صفاتهم ملازمة ذكر الله وعدم الغفلة، فإذا فعلوا فاحشة أو ظلموا أنفسهم بذنب دونها ذكروا وعيد الله ونهيه، فبادروا إلى التوبة: الإقلاع عن الذنب، والندم، والعزم على عدم العودة، واستغفار الله منه، ولم يواظبوا على الذنب وهم يعلمون أنه ذنب. وجزاؤهم مغفرة ذنوبهم كلها، والخلود في الجنة ذات النعيم المقيم، ونعم أجر العاملين.", "h": ["وجوب تعجيل التوبة وعدم التسويف فيها، لقوله: «سارعوا».", "سعة الجنة، وأنها مخلوقة الآن، لقوله: «أُعدّت».", "المتقون هم أهل الجنة وورثتها بحق.", "فضل استمرار الإنفاق في سبيل الله ولو بالقليل.", "فضيلة كظم الغيظ بترك المبادرة إلى التشفي والانتقام.", "فضل العفو عن الناس مطلقاً: مؤمنهم وكافرهم، بارّهم وفاجرهم.", "فضيلة الاستغفار وترك الإصرار على المعصية، للآية ولحديث: «ما أصرّ من استغفر ولو عاد في اليوم سبعين مرة»."], "k": "آخر مرة غضبت فيها… هل كظمتُ غيظي؟ ومن أحتاج أن أعفو عنه اليوم؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (58, 3, 137, 148, 'سورة آل عمران ١٣٧ – ١٤٨', 'دروس أُحد: الأيام دُوَل، وما محمد إلا رسول', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 58) = $j$[{"lbl": "الآيات ١٣٧ – ١٤١", "q": "قَدۡ خَلَتۡ مِن قَبۡلِكُمۡ سُنَنٞ فَسِيرُواْ فِي ٱلۡأَرۡضِ فَٱنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُكَذِّبِينَ ﴿١٣٧﴾ هَٰذَا بَيَانٞ لِّلنَّاسِ وَهُدٗى وَمَوۡعِظَةٞ لِّلۡمُتَّقِينَ ﴿١٣٨﴾ وَلَا تَهِنُواْ وَلَا تَحۡزَنُواْ وَأَنتُمُ ٱلۡأَعۡلَوۡنَ إِن كُنتُم مُّؤۡمِنِينَ ﴿١٣٩﴾ إِن يَمۡسَسۡكُمۡ قَرۡحٞ فَقَدۡ مَسَّ ٱلۡقَوۡمَ قَرۡحٞ مِّثۡلُهُۥۚ وَتِلۡكَ ٱلۡأَيَّامُ نُدَاوِلُهَا بَيۡنَ ٱلنَّاسِ وَلِيَعۡلَمَ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ وَيَتَّخِذَ مِنكُمۡ شُهَدَآءَۗ وَٱللَّهُ لَا يُحِبُّ ٱلظَّـٰلِمِينَ ﴿١٤٠﴾ وَلِيُمَحِّصَ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ وَيَمۡحَقَ ٱلۡكَٰفِرِينَ ﴿١٤١﴾", "w": [["قد خلت", "مضت."], ["سنن", "جمع سنّة: السيرة والطريقة، وسنن الله في خلقه قانونه الماضي فيهم."], ["عاقبة المكذبين", "ما حلّ بهم من الدمار والخسار كعاد وثمود."], ["هذا بيان للناس", "ما ذُكر في الآيات بيان يتبيّن به الناس الهدى من الضلال."], ["موعظة", "ما يتّعظ به المؤمن فيسلك سبيل النجاة."], ["ولا تهنوا", "لا تضعفوا."], ["قرح", "أثر السلاح في الجسم كالجرح."], ["الأيام", "المراد ما يجريه الله من تصاريف الحياة من خير وغيره وإعزاز وإذلال."], ["شهداء", "جمع شهيد، وهو المقتول في سبيل الله."], ["وليمحّص", "ليخلّص المؤمنين من أدران المخالفات والذنوب."], ["ويمحق", "يمحو ويُذهب آثار الكفر والكافرين."]], "m": "لما حدث ما حدث من انكسار المؤمنين بسبب عدم الصبر والطاعة اللازمة للقيادة، ذكر الله تلك الأحداث مقرونة بفقهها لتبقى هدى وموعظة: قد مضت سنن الله فيمن قبلكم كقوم نوح وعاد وثمود، كذّبوا رسلهم فأهلك المكذبين وأنجى المؤمنين بعد ما نالهم من الأذى، وستمضي سنته اليوم كذلك، وإن ارتبتم فسيروا في الأرض فانظروا آثار الهالكين. ثم عزّاهم فيما أصابهم يوم أحد: لا تضعفوا فتقعدوا عن الجهاد، ولا تحزنوا على من فاتكم من رجالكم، وأنتم الأعلون بشرط إيمانكم وتقواكم؛ وإن أصابكم قرح فقد أصاب عدوكم قرح مثله في بدر، والحرب سِجال، يوم لكم ويوم عليكم، وتلك الأيام نداولها بين الناس. ثم ذكر الحكمة: ليظهر إيمان المؤمنين، فقد رجع المنافقون من الطريق بزعامة عبد الله بن أُبيّ، وواصل المؤمنون فظهر إيمانهم، واتخذ الله منهم نحو سبعين شهيداً، منهم حمزة بن عبد المطلب ومصعب بن عمير، وليخلّص المؤمنين من ذنوبهم ويمحق الكافرين. وقد نفعهم هذا الدرس، فلم يخرجوا بعده عن طاعة نبيهم ﷺ، فتوالت انتصاراتهم.", "h": ["عاقبة المكذبين بدعوة الحق الخسار والوبال.", "في آي القرآن الهدى والبيان والمواعظ لمن كان من أهل الإيمان والتقوى.", "أهل الإيمان هم الأعلون في الدنيا والآخرة.", "الحياة دول وتارات، فليقابلها المؤمن بالشكر والصبر.", "الفتن تمحّص الرجال، وتودي بالعاجزين الجزعين."], "k": "«وتلك الأيام نداولها بين الناس»… كيف أستقبل يوم الشدة القادم في حياتي: بجزع أم بصبر؟"}, {"lbl": "الآيات ١٤٢ – ١٤٥", "q": "أَمۡ حَسِبۡتُمۡ أَن تَدۡخُلُواْ ٱلۡجَنَّةَ وَلَمَّا يَعۡلَمِ ٱللَّهُ ٱلَّذِينَ جَٰهَدُواْ مِنكُمۡ وَيَعۡلَمَ ٱلصَّـٰبِرِينَ ﴿١٤٢﴾ وَلَقَدۡ كُنتُمۡ تَمَنَّوۡنَ ٱلۡمَوۡتَ مِن قَبۡلِ أَن تَلۡقَوۡهُ فَقَدۡ رَأَيۡتُمُوهُ وَأَنتُمۡ تَنظُرُونَ ﴿١٤٣﴾ وَمَا مُحَمَّدٌ إِلَّا رَسُولٞ قَدۡ خَلَتۡ مِن قَبۡلِهِ ٱلرُّسُلُۚ أَفَإِيْن مَّاتَ أَوۡ قُتِلَ ٱنقَلَبۡتُمۡ عَلَىٰٓ أَعۡقَٰبِكُمۡۚ وَمَن يَنقَلِبۡ عَلَىٰ عَقِبَيۡهِ فَلَن يَضُرَّ ٱللَّهَ شَيۡـٔٗاۚ وَسَيَجۡزِي ٱللَّهُ ٱلشَّـٰكِرِينَ ﴿١٤٤﴾ وَمَا كَانَ لِنَفۡسٍ أَن تَمُوتَ إِلَّا بِإِذۡنِ ٱللَّهِ كِتَٰبٗا مُّؤَجَّلٗاۗ وَمَن يُرِدۡ ثَوَابَ ٱلدُّنۡيَا نُؤۡتِهِۦ مِنۡهَا وَمَن يُرِدۡ ثَوَابَ ٱلۡأٓخِرَةِ نُؤۡتِهِۦ مِنۡهَاۚ وَسَنَجۡزِي ٱلشَّـٰكِرِينَ ﴿١٤٥﴾", "w": [["أم حسبتم", "استفهام إنكاري."], ["ولمّا يعلم الله", "ولم يبتلكم بالجهاد حتى يعلم علم ظهور من يجاهد منكم ممن لا يجاهد، وهو عالم به في باطن الأمر."], ["خلت من قبله الرسل", "مضت من قبله الرسل، بلّغوا رسالتهم وماتوا."], ["انقلبتم على أعقابكم", "رجعتم عن الإسلام إلى الكفر."], ["كتاباً مؤجلاً", "كتب الله آجال الناس مؤقتة بمواقيتها، فلا تتقدم ولا تتأخر."], ["ثواب الدنيا", "الثواب: الجزاء على النية والعمل معاً، وثواب الدنيا الرزق، وثواب الآخرة الجنة."], ["الشاكرين", "الذين ثبتوا على إسلامهم، فاعتُبر ثباتهم شكراً لله."]], "m": "ما زال السياق في غزوة أحد، فأنكر الله على المؤمنين ظنّهم أنهم يدخلون الجنة بمجرد إيمانهم دون أن يُبتلوا بالجهاد والشدائد، تمحيصاً لهم وإظهاراً للصادقين من الكاذبين. ثم عاب عليهم قلة صبرهم وانهزامهم، وقد كان الذين فاتتهم بدر يتمنّون يوماً يبلون فيه البلاء الحسن، فلما جاء يوم أحد جزعوا وفرّوا: «ولقد كنتم تمنّون الموت من قبل أن تلقوه فقد رأيتموه وأنتم تنظرون». ولما خلت ظهورهم من الرماة واستحرّ القتل فيهم، وضرب ابن قمئة رسول الله ﷺ بحجر فشجّه وكسر رباعيته وأعلن أنه قتل محمداً، انكشف المسلمون، وقال بعضهم: لِمَ نقاتل وقد مات رسول الله؟ وقال بعض المنافقين: نعود إلى دين قومنا! فقال تعالى: «وما محمد إلا رسول قد خلت من قبله الرسل»، فلِمَ يُنكر موته؟ ثم أنكر بشدة على من فرّ أو ارتدّ: «أفإن مات أو قتل انقلبتم على أعقابكم»، ومن ينقلب فلن يضرّ الله شيئاً، وسيجزي الله الثابتين على إيمانهم. ثم قرّر حقيقتين: أن موت كل نفس بإذن الله، في كتاب مؤجّل لا يتقدم ولا يتأخر، وأن من أراد بعمله ثواب الدنيا آتاه الله منها ما قدّر له وليس له في الآخرة شيء، ومن أراد ثواب الآخرة آتاه الله ما كتب له في الدنيا وأعطاه الجنة.", "h": ["الابتلاء بالتكاليف الشرعية، الصعبة منها والسهلة، من ضروريات الإيمان.", "تقرير رسالة النبي محمد ﷺ وبشريته المفضّلة، وموته المؤلم لكل مؤمن.", "الجهاد وخوض المعارك لا يقدّم أجل العبد، والفرار من الجهاد لا يؤخّره أيضاً.", "ثواب الأعمال موقوف على نية العاملين وحسن قصدهم.", "فضيلة الشكر بالثبات على الإيمان والطاعة لله ورسوله في الأمر والنهي."], "k": "«ومن يرد ثواب الآخرة نؤته منها»… ماذا أريد حقاً بأكثر عمل أتعب فيه هذه الأيام؟"}, {"lbl": "الآيات ١٤٦ – ١٤٨", "q": "وَكَأَيِّن مِّن نَّبِيّٖ قَٰتَلَ مَعَهُۥ رِبِّيُّونَ كَثِيرٞ فَمَا وَهَنُواْ لِمَآ أَصَابَهُمۡ فِي سَبِيلِ ٱللَّهِ وَمَا ضَعُفُواْ وَمَا ٱسۡتَكَانُواْۗ وَٱللَّهُ يُحِبُّ ٱلصَّـٰبِرِينَ ﴿١٤٦﴾ وَمَا كَانَ قَوۡلَهُمۡ إِلَّآ أَن قَالُواْ رَبَّنَا ٱغۡفِرۡ لَنَا ذُنُوبَنَا وَإِسۡرَافَنَا فِيٓ أَمۡرِنَا وَثَبِّتۡ أَقۡدَامَنَا وَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ ﴿١٤٧﴾ فَـَٔاتَىٰهُمُ ٱللَّهُ ثَوَابَ ٱلدُّنۡيَا وَحُسۡنَ ثَوَابِ ٱلۡأٓخِرَةِۗ وَٱللَّهُ يُحِبُّ ٱلۡمُحۡسِنِينَ ﴿١٤٨﴾", "w": [["وكأيّن من نبي", "كثير من الأنبياء."], ["ربّيون", "ربانيون: علماء وصلحاء وأتقياء عابدون."], ["فما وهنوا لما أصابهم", "ما ضعفوا عن القتال ولا انهزموا لأجل ما أصابهم من قتل وجراحات."], ["وما استكانوا", "ما خضعوا ولا ذلّوا لعدوهم."], ["وإسرافنا", "الإسراف: مجاوزة الحد في الأمور التي ينبغي أن يُوقف عندها."], ["فآتاهم الله ثواب الدنيا", "أعطاهم النصر والغنيمة."]], "m": "ما زال السياق في أحداث أحد، تتمةً لعتاب المؤمنين على عدم صبرهم وتخلّيهم عن نبيهم ﷺ في وسط المعركة حتى ناداهم: «إليّ عباد الله، إليّ عباد الله». فأخبر بما يكون عظة لهم: كم من نبي قاتل معه جموع كثيرة من العلماء والأتقياء، فما ضعفوا ولا ذلّوا لعدوهم كما همّ بعضكم أن يفعل، بل صبروا على القتال مع أنبيائهم فأحبّهم الله لأنه يحب الصابرين. وما كان قولهم أثناء الجهاد إلا الضراعة لله: «ربنا اغفر لنا ذنوبنا وإسرافنا في أمرنا وثبّت أقدامنا وانصرنا على القوم الكافرين»، فكأنه يقول للمؤمنين: لِمَ لا تكونون مثلهم وتقولون قولتهم، والذنوب كثيراً ما تكون سبباً للهزائم كما حصل لكم؟ فسألوا مغفرة ذنوبهم وتثبيت أقدامهم والنصر، فاستجاب لهم ربهم فأعطاهم ثواب الدنيا بالنصر والتمكين، وحسن ثواب الآخرة وهو رضوانه في الجنة، والله يحب المحسنين.", "h": ["الترغيب في الائتساء بالصالحين في إيمانهم وجهادهم وصبرهم وحسن أقوالهم.", "فضيلة الصبر والإحسان، لحب الله تعالى الصابرين والمحسنين.", "فضيلة الاشتغال بالذكر والدعاء عند المصائب والشدائد بدل التأوّهات والتحسّرات، وشرٌّ من ذلك التسخّط والتضجّر والعويل.", "كرم الله تعالى المتجلّي في استجابة دعاء عباده الصابرين المحسنين."], "k": "عند المصيبة القادمة… هل سيسبق لساني «ربنا اغفر لنا وثبّت أقدامنا» أم التحسّر والشكوى؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 58;
insert into public.tdb_cards(topic, i, body) select 58, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٣٧ – ١٤١", "q": "قَدۡ خَلَتۡ مِن قَبۡلِكُمۡ سُنَنٞ فَسِيرُواْ فِي ٱلۡأَرۡضِ فَٱنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُكَذِّبِينَ ﴿١٣٧﴾ هَٰذَا بَيَانٞ لِّلنَّاسِ وَهُدٗى وَمَوۡعِظَةٞ لِّلۡمُتَّقِينَ ﴿١٣٨﴾ وَلَا تَهِنُواْ وَلَا تَحۡزَنُواْ وَأَنتُمُ ٱلۡأَعۡلَوۡنَ إِن كُنتُم مُّؤۡمِنِينَ ﴿١٣٩﴾ إِن يَمۡسَسۡكُمۡ قَرۡحٞ فَقَدۡ مَسَّ ٱلۡقَوۡمَ قَرۡحٞ مِّثۡلُهُۥۚ وَتِلۡكَ ٱلۡأَيَّامُ نُدَاوِلُهَا بَيۡنَ ٱلنَّاسِ وَلِيَعۡلَمَ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ وَيَتَّخِذَ مِنكُمۡ شُهَدَآءَۗ وَٱللَّهُ لَا يُحِبُّ ٱلظَّـٰلِمِينَ ﴿١٤٠﴾ وَلِيُمَحِّصَ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ وَيَمۡحَقَ ٱلۡكَٰفِرِينَ ﴿١٤١﴾", "w": [["قد خلت", "مضت."], ["سنن", "جمع سنّة: السيرة والطريقة، وسنن الله في خلقه قانونه الماضي فيهم."], ["عاقبة المكذبين", "ما حلّ بهم من الدمار والخسار كعاد وثمود."], ["هذا بيان للناس", "ما ذُكر في الآيات بيان يتبيّن به الناس الهدى من الضلال."], ["موعظة", "ما يتّعظ به المؤمن فيسلك سبيل النجاة."], ["ولا تهنوا", "لا تضعفوا."], ["قرح", "أثر السلاح في الجسم كالجرح."], ["الأيام", "المراد ما يجريه الله من تصاريف الحياة من خير وغيره وإعزاز وإذلال."], ["شهداء", "جمع شهيد، وهو المقتول في سبيل الله."], ["وليمحّص", "ليخلّص المؤمنين من أدران المخالفات والذنوب."], ["ويمحق", "يمحو ويُذهب آثار الكفر والكافرين."]], "m": "لما حدث ما حدث من انكسار المؤمنين بسبب عدم الصبر والطاعة اللازمة للقيادة، ذكر الله تلك الأحداث مقرونة بفقهها لتبقى هدى وموعظة: قد مضت سنن الله فيمن قبلكم كقوم نوح وعاد وثمود، كذّبوا رسلهم فأهلك المكذبين وأنجى المؤمنين بعد ما نالهم من الأذى، وستمضي سنته اليوم كذلك، وإن ارتبتم فسيروا في الأرض فانظروا آثار الهالكين. ثم عزّاهم فيما أصابهم يوم أحد: لا تضعفوا فتقعدوا عن الجهاد، ولا تحزنوا على من فاتكم من رجالكم، وأنتم الأعلون بشرط إيمانكم وتقواكم؛ وإن أصابكم قرح فقد أصاب عدوكم قرح مثله في بدر، والحرب سِجال، يوم لكم ويوم عليكم، وتلك الأيام نداولها بين الناس. ثم ذكر الحكمة: ليظهر إيمان المؤمنين، فقد رجع المنافقون من الطريق بزعامة عبد الله بن أُبيّ، وواصل المؤمنون فظهر إيمانهم، واتخذ الله منهم نحو سبعين شهيداً، منهم حمزة بن عبد المطلب ومصعب بن عمير، وليخلّص المؤمنين من ذنوبهم ويمحق الكافرين. وقد نفعهم هذا الدرس، فلم يخرجوا بعده عن طاعة نبيهم ﷺ، فتوالت انتصاراتهم.", "h": ["عاقبة المكذبين بدعوة الحق الخسار والوبال.", "في آي القرآن الهدى والبيان والمواعظ لمن كان من أهل الإيمان والتقوى.", "أهل الإيمان هم الأعلون في الدنيا والآخرة.", "الحياة دول وتارات، فليقابلها المؤمن بالشكر والصبر.", "الفتن تمحّص الرجال، وتودي بالعاجزين الجزعين."], "k": "«وتلك الأيام نداولها بين الناس»… كيف أستقبل يوم الشدة القادم في حياتي: بجزع أم بصبر؟"}, {"lbl": "الآيات ١٤٢ – ١٤٥", "q": "أَمۡ حَسِبۡتُمۡ أَن تَدۡخُلُواْ ٱلۡجَنَّةَ وَلَمَّا يَعۡلَمِ ٱللَّهُ ٱلَّذِينَ جَٰهَدُواْ مِنكُمۡ وَيَعۡلَمَ ٱلصَّـٰبِرِينَ ﴿١٤٢﴾ وَلَقَدۡ كُنتُمۡ تَمَنَّوۡنَ ٱلۡمَوۡتَ مِن قَبۡلِ أَن تَلۡقَوۡهُ فَقَدۡ رَأَيۡتُمُوهُ وَأَنتُمۡ تَنظُرُونَ ﴿١٤٣﴾ وَمَا مُحَمَّدٌ إِلَّا رَسُولٞ قَدۡ خَلَتۡ مِن قَبۡلِهِ ٱلرُّسُلُۚ أَفَإِيْن مَّاتَ أَوۡ قُتِلَ ٱنقَلَبۡتُمۡ عَلَىٰٓ أَعۡقَٰبِكُمۡۚ وَمَن يَنقَلِبۡ عَلَىٰ عَقِبَيۡهِ فَلَن يَضُرَّ ٱللَّهَ شَيۡـٔٗاۚ وَسَيَجۡزِي ٱللَّهُ ٱلشَّـٰكِرِينَ ﴿١٤٤﴾ وَمَا كَانَ لِنَفۡسٍ أَن تَمُوتَ إِلَّا بِإِذۡنِ ٱللَّهِ كِتَٰبٗا مُّؤَجَّلٗاۗ وَمَن يُرِدۡ ثَوَابَ ٱلدُّنۡيَا نُؤۡتِهِۦ مِنۡهَا وَمَن يُرِدۡ ثَوَابَ ٱلۡأٓخِرَةِ نُؤۡتِهِۦ مِنۡهَاۚ وَسَنَجۡزِي ٱلشَّـٰكِرِينَ ﴿١٤٥﴾", "w": [["أم حسبتم", "استفهام إنكاري."], ["ولمّا يعلم الله", "ولم يبتلكم بالجهاد حتى يعلم علم ظهور من يجاهد منكم ممن لا يجاهد، وهو عالم به في باطن الأمر."], ["خلت من قبله الرسل", "مضت من قبله الرسل، بلّغوا رسالتهم وماتوا."], ["انقلبتم على أعقابكم", "رجعتم عن الإسلام إلى الكفر."], ["كتاباً مؤجلاً", "كتب الله آجال الناس مؤقتة بمواقيتها، فلا تتقدم ولا تتأخر."], ["ثواب الدنيا", "الثواب: الجزاء على النية والعمل معاً، وثواب الدنيا الرزق، وثواب الآخرة الجنة."], ["الشاكرين", "الذين ثبتوا على إسلامهم، فاعتُبر ثباتهم شكراً لله."]], "m": "ما زال السياق في غزوة أحد، فأنكر الله على المؤمنين ظنّهم أنهم يدخلون الجنة بمجرد إيمانهم دون أن يُبتلوا بالجهاد والشدائد، تمحيصاً لهم وإظهاراً للصادقين من الكاذبين. ثم عاب عليهم قلة صبرهم وانهزامهم، وقد كان الذين فاتتهم بدر يتمنّون يوماً يبلون فيه البلاء الحسن، فلما جاء يوم أحد جزعوا وفرّوا: «ولقد كنتم تمنّون الموت من قبل أن تلقوه فقد رأيتموه وأنتم تنظرون». ولما خلت ظهورهم من الرماة واستحرّ القتل فيهم، وضرب ابن قمئة رسول الله ﷺ بحجر فشجّه وكسر رباعيته وأعلن أنه قتل محمداً، انكشف المسلمون، وقال بعضهم: لِمَ نقاتل وقد مات رسول الله؟ وقال بعض المنافقين: نعود إلى دين قومنا! فقال تعالى: «وما محمد إلا رسول قد خلت من قبله الرسل»، فلِمَ يُنكر موته؟ ثم أنكر بشدة على من فرّ أو ارتدّ: «أفإن مات أو قتل انقلبتم على أعقابكم»، ومن ينقلب فلن يضرّ الله شيئاً، وسيجزي الله الثابتين على إيمانهم. ثم قرّر حقيقتين: أن موت كل نفس بإذن الله، في كتاب مؤجّل لا يتقدم ولا يتأخر، وأن من أراد بعمله ثواب الدنيا آتاه الله منها ما قدّر له وليس له في الآخرة شيء، ومن أراد ثواب الآخرة آتاه الله ما كتب له في الدنيا وأعطاه الجنة.", "h": ["الابتلاء بالتكاليف الشرعية، الصعبة منها والسهلة، من ضروريات الإيمان.", "تقرير رسالة النبي محمد ﷺ وبشريته المفضّلة، وموته المؤلم لكل مؤمن.", "الجهاد وخوض المعارك لا يقدّم أجل العبد، والفرار من الجهاد لا يؤخّره أيضاً.", "ثواب الأعمال موقوف على نية العاملين وحسن قصدهم.", "فضيلة الشكر بالثبات على الإيمان والطاعة لله ورسوله في الأمر والنهي."], "k": "«ومن يرد ثواب الآخرة نؤته منها»… ماذا أريد حقاً بأكثر عمل أتعب فيه هذه الأيام؟"}, {"lbl": "الآيات ١٤٦ – ١٤٨", "q": "وَكَأَيِّن مِّن نَّبِيّٖ قَٰتَلَ مَعَهُۥ رِبِّيُّونَ كَثِيرٞ فَمَا وَهَنُواْ لِمَآ أَصَابَهُمۡ فِي سَبِيلِ ٱللَّهِ وَمَا ضَعُفُواْ وَمَا ٱسۡتَكَانُواْۗ وَٱللَّهُ يُحِبُّ ٱلصَّـٰبِرِينَ ﴿١٤٦﴾ وَمَا كَانَ قَوۡلَهُمۡ إِلَّآ أَن قَالُواْ رَبَّنَا ٱغۡفِرۡ لَنَا ذُنُوبَنَا وَإِسۡرَافَنَا فِيٓ أَمۡرِنَا وَثَبِّتۡ أَقۡدَامَنَا وَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ ﴿١٤٧﴾ فَـَٔاتَىٰهُمُ ٱللَّهُ ثَوَابَ ٱلدُّنۡيَا وَحُسۡنَ ثَوَابِ ٱلۡأٓخِرَةِۗ وَٱللَّهُ يُحِبُّ ٱلۡمُحۡسِنِينَ ﴿١٤٨﴾", "w": [["وكأيّن من نبي", "كثير من الأنبياء."], ["ربّيون", "ربانيون: علماء وصلحاء وأتقياء عابدون."], ["فما وهنوا لما أصابهم", "ما ضعفوا عن القتال ولا انهزموا لأجل ما أصابهم من قتل وجراحات."], ["وما استكانوا", "ما خضعوا ولا ذلّوا لعدوهم."], ["وإسرافنا", "الإسراف: مجاوزة الحد في الأمور التي ينبغي أن يُوقف عندها."], ["فآتاهم الله ثواب الدنيا", "أعطاهم النصر والغنيمة."]], "m": "ما زال السياق في أحداث أحد، تتمةً لعتاب المؤمنين على عدم صبرهم وتخلّيهم عن نبيهم ﷺ في وسط المعركة حتى ناداهم: «إليّ عباد الله، إليّ عباد الله». فأخبر بما يكون عظة لهم: كم من نبي قاتل معه جموع كثيرة من العلماء والأتقياء، فما ضعفوا ولا ذلّوا لعدوهم كما همّ بعضكم أن يفعل، بل صبروا على القتال مع أنبيائهم فأحبّهم الله لأنه يحب الصابرين. وما كان قولهم أثناء الجهاد إلا الضراعة لله: «ربنا اغفر لنا ذنوبنا وإسرافنا في أمرنا وثبّت أقدامنا وانصرنا على القوم الكافرين»، فكأنه يقول للمؤمنين: لِمَ لا تكونون مثلهم وتقولون قولتهم، والذنوب كثيراً ما تكون سبباً للهزائم كما حصل لكم؟ فسألوا مغفرة ذنوبهم وتثبيت أقدامهم والنصر، فاستجاب لهم ربهم فأعطاهم ثواب الدنيا بالنصر والتمكين، وحسن ثواب الآخرة وهو رضوانه في الجنة، والله يحب المحسنين.", "h": ["الترغيب في الائتساء بالصالحين في إيمانهم وجهادهم وصبرهم وحسن أقوالهم.", "فضيلة الصبر والإحسان، لحب الله تعالى الصابرين والمحسنين.", "فضيلة الاشتغال بالذكر والدعاء عند المصائب والشدائد بدل التأوّهات والتحسّرات، وشرٌّ من ذلك التسخّط والتضجّر والعويل.", "كرم الله تعالى المتجلّي في استجابة دعاء عباده الصابرين المحسنين."], "k": "عند المصيبة القادمة… هل سيسبق لساني «ربنا اغفر لنا وثبّت أقدامنا» أم التحسّر والشكوى؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (59, 3, 149, 155, 'سورة آل عمران ١٤٩ – ١٥٥', 'لا تطيعوا الكافرين، وكيف وقعت الهزيمة في أُحد', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 59) = $j$[{"lbl": "الآيات ١٤٩ – ١٥١", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِن تُطِيعُواْ ٱلَّذِينَ كَفَرُواْ يَرُدُّوكُمۡ عَلَىٰٓ أَعۡقَٰبِكُمۡ فَتَنقَلِبُواْ خَٰسِرِينَ ﴿١٤٩﴾ بَلِ ٱللَّهُ مَوۡلَىٰكُمۡۖ وَهُوَ خَيۡرُ ٱلنَّـٰصِرِينَ ﴿١٥٠﴾ سَنُلۡقِي فِي قُلُوبِ ٱلَّذِينَ كَفَرُواْ ٱلرُّعۡبَ بِمَآ أَشۡرَكُواْ بِٱللَّهِ مَا لَمۡ يُنَزِّلۡ بِهِۦ سُلۡطَٰنٗاۖ وَمَأۡوَىٰهُمُ ٱلنَّارُۖ وَبِئۡسَ مَثۡوَى ٱلظَّـٰلِمِينَ ﴿١٥١﴾", "w": [["إن تطيعوا الذين كفروا", "المراد قبول قولهم والأخذ بإرشاداتهم."], ["يردّوكم على أعقابكم", "يرجعوكم إلى الكفر بعد الإيمان."], ["خاسرين", "فاقدين لكل خير في الدنيا، ولأنفسكم وأهليكم يوم القيامة."], ["بل الله مولاكم", "بل أطيعوا الله ربكم ووليكم، فإنه خير من يُطاع وأحق من يُطاع."], ["الرعب", "شدة الخوف من توقّع الهزيمة والمكروه."], ["مأواهم", "مقرّ إيوائهم ونزولهم."], ["مثوى", "مكان الإقامة والاستقرار."], ["الظالمين", "المشركين الذين أطاعوا غير الله وعبدوا سواه."]], "m": "ما زال السياق في أحداث أحد؛ رُوي أن بعض المنافقين لما رأى هزيمة المؤمنين قال: ارجعوا إلى دينكم وإخوانكم، ولو كان محمد نبياً لما قُتل. فحذّر الله المؤمنين من طاعة الكافرين: إن تطيعوهم يردّوكم على أعقابكم فتنقلبوا خاسرين؛ فهم يقترحون ما ظاهره النصح وباطنه الغش والخديعة، وهذا النهي وإن نزل في حالة خاصة فهو عام في المسلمين على مدى الحياة. ثم أمرهم بطاعته فهو مولاهم وأحق بطاعتهم، وإن أرادوا النصر فهو خير الناصرين، فليطلبوه منه بطاعته. ثم بشّرهم بأنه سيلقي في قلوب الكافرين الرعب حتى يتمكّنوا منهم، بسبب إشراكهم به آلهة لم ينزل بعبادتها حجة ولا سلطاناً، ومأواهم النار، وبئس مثوى الظالمين.", "h": ["تحريم طاعة الكافرين في حال الاختيار.", "بيان السر في تحريم طاعة الكافرين، وهو أنه يترتب عليها الردة والعياذ بالله.", "بيان قاعدة: من طلب النصر من غير الله أذلّه الله.", "وعد الله المؤمنين بنصرهم بعد إلقاء الرعب في قلوب أعدائهم؛ إذ همّ أبو سفيان بالعودة إلى المدينة بعد انصرافه من أحد، ثم ألقى الله في قلبه الرعب فعدل عن ذلك.", "بطلان كل دعوى ما لم يكن لأصحابها حجة، وهي المعبَّر عنها بالسلطان في الآية."], "k": "لمن أستمع حين أتخذ قراراتي؟ وهل يوافق ما يشيرون به أمرَ الله؟"}, {"lbl": "الآيتان ١٥٢ – ١٥٣", "q": "وَلَقَدۡ صَدَقَكُمُ ٱللَّهُ وَعۡدَهُۥٓ إِذۡ تَحُسُّونَهُم بِإِذۡنِهِۦۖ حَتَّىٰٓ إِذَا فَشِلۡتُمۡ وَتَنَٰزَعۡتُمۡ فِي ٱلۡأَمۡرِ وَعَصَيۡتُم مِّنۢ بَعۡدِ مَآ أَرَىٰكُم مَّا تُحِبُّونَۚ مِنكُم مَّن يُرِيدُ ٱلدُّنۡيَا وَمِنكُم مَّن يُرِيدُ ٱلۡأٓخِرَةَۚ ثُمَّ صَرَفَكُمۡ عَنۡهُمۡ لِيَبۡتَلِيَكُمۡۖ وَلَقَدۡ عَفَا عَنكُمۡۗ وَٱللَّهُ ذُو فَضۡلٍ عَلَى ٱلۡمُؤۡمِنِينَ ﴿١٥٢﴾ ۞إِذۡ تُصۡعِدُونَ وَلَا تَلۡوُۥنَ عَلَىٰٓ أَحَدٖ وَٱلرَّسُولُ يَدۡعُوكُمۡ فِيٓ أُخۡرَىٰكُمۡ فَأَثَٰبَكُمۡ غَمَّۢا بِغَمّٖ لِّكَيۡلَا تَحۡزَنُواْ عَلَىٰ مَا فَاتَكُمۡ وَلَا مَآ أَصَٰبَكُمۡۗ وَٱللَّهُ خَبِيرُۢ بِمَا تَعۡمَلُونَ ﴿١٥٣﴾", "w": [["صدقكم الله وعده", "أنجز لكم ما وعدكم على لسان رسوله ﷺ بقوله للرماة: اثبتوا أماكنكم فإنا لا نزال غالبين ما ثبتّم."], ["تحسّونهم", "تقتلونهم."], ["بإذنه", "بإذنه لكم في قتالهم وإعانته لكم على ذلك."], ["فشلتم", "ضعفتم وجبنتم عن القتال."], ["وتنازعتم في الأمر", "في أمركم وشأنكم."], ["تُصعدون", "تذهبون في الأرض فارّين من المعركة."], ["ولا تلوون على أحد", "لا تلتفتون إلى أحد."], ["والرسول يدعوكم في أخراكم", "يناديكم من خلفكم: إليّ عباد الله، ارجعوا."], ["فأثابكم غمّاً بغم", "جزاكم على معصيتكم وفراركم غمّاً على غمّ، والغمّ: ألم النفس وضيق الصدر."], ["ولا ما أصابكم", "من الموت والجراحات والآلام."]], "m": "لما بوّأ النبي ﷺ الرماة مقاعدهم، وكانوا ثلاثين رامياً عليهم عبد الله بن جبير، أمرهم ألا يبرحوا أماكنهم كيفما كانت الحال. ودارت المعركة فأنجز الله وعده، ففرّ المشركون والمؤمنون يقتلونهم بإذن الله. فلما رأى الرماة الهزيمة والمؤمنون يجمعون الغنائم قالوا: ما قيمة بقائنا هنا؟ فذكّرهم قائدهم بأمر رسول الله ﷺ، فتأوّلوه ونزلوا. وكان على خيل المشركين خالد بن الوليد، فلما رأى الرماة أخلّوا مراكزهم كرّ عليهم فاحتلّ أماكنهم وقتل من بقي ورمى المسلمين من ظهورهم، فوقعت الكارثة: قُتل سبعون من المؤمنين منهم حمزة، وجُرح رسول الله ﷺ، وصاح الشيطان: إن محمداً قد مات، ففرّ المؤمنون إلا قليلاً. وهذا معنى: «حتى إذا فشلتم وتنازعتم في الأمر وعصيتم من بعد ما أراكم ما تحبون»، فمنكم من يريد الدنيا وهم الذين نزلوا للغنائم، ومنكم من يريد الآخرة وهم ابن جبير ومن صبر معه حتى استُشهدوا. ثم صرفكم عنهم ليختبركم فيظهر الصادق من المنافق، ولقد عفا عنكم، ولو شاء لسلّط عليكم المشركين فاستأصلوكم. ثم صوّر حالهم وهم يفرّون في الوادي والرسول ﷺ يدعوهم من خلفهم، فجزاهم غمّاً على غمّ: غمّ فوات النصر والغنيمة، ثم غمّ القتل والجراحات وإشاعة قتل النبي ﷺ، فأنساهم الغمُّ الثاني الأول، لكيلا يحزنوا على ما فاتهم ولا ما أصابهم، والله خبير بما يعملون.", "h": ["مخالفة القيادة الرشيدة والتنازع في حال الحرب يسبب الهزيمة المنكرة.", "معصية الله ورسوله والاختلافات بين أفراد الأمة تُعقب آثاراً سيئة، أخفّها عقوبة الدنيا بالهزائم وذهاب الدولة والسلطان.", "ما من مصيبة تصيب العبد إلا وعند الله ما هو أعظم منها، فلذا يجب حمد الله على أنها لم تكن أعظم.", "ظاهر هزيمة أحد النقمة وباطنها النعمة؛ إذ علم المؤمنون أن النصر والهزيمة يتمّان حسب سنن إلهية، فما أصبحوا بعدها يغفلون تلك السنن أو يهملونها.", "معصية الرسول ﷺ مرة واحدة في شيء واحد ترتّب عليها آلام وجراحات وقتل وهزائم وفوات خير كثير، فكيف بالذين يعصونه طوال حياتهم في كل أوامره ونواهيه وهم آمنون غير خائفين؟"], "k": "معصية واحدة غيّرت نتيجة معركة… فما المعصية التي أستهين بها وأنا آمن؟"}, {"lbl": "الآيتان ١٥٤ – ١٥٥", "q": "ثُمَّ أَنزَلَ عَلَيۡكُم مِّنۢ بَعۡدِ ٱلۡغَمِّ أَمَنَةٗ نُّعَاسٗا يَغۡشَىٰ طَآئِفَةٗ مِّنكُمۡۖ وَطَآئِفَةٞ قَدۡ أَهَمَّتۡهُمۡ أَنفُسُهُمۡ يَظُنُّونَ بِٱللَّهِ غَيۡرَ ٱلۡحَقِّ ظَنَّ ٱلۡجَٰهِلِيَّةِۖ يَقُولُونَ هَل لَّنَا مِنَ ٱلۡأَمۡرِ مِن شَيۡءٖۗ قُلۡ إِنَّ ٱلۡأَمۡرَ كُلَّهُۥ لِلَّهِۗ يُخۡفُونَ فِيٓ أَنفُسِهِم مَّا لَا يُبۡدُونَ لَكَۖ يَقُولُونَ لَوۡ كَانَ لَنَا مِنَ ٱلۡأَمۡرِ شَيۡءٞ مَّا قُتِلۡنَا هَٰهُنَاۗ قُل لَّوۡ كُنتُمۡ فِي بُيُوتِكُمۡ لَبَرَزَ ٱلَّذِينَ كُتِبَ عَلَيۡهِمُ ٱلۡقَتۡلُ إِلَىٰ مَضَاجِعِهِمۡۖ وَلِيَبۡتَلِيَ ٱللَّهُ مَا فِي صُدُورِكُمۡ وَلِيُمَحِّصَ مَا فِي قُلُوبِكُمۡۚ وَٱللَّهُ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ ﴿١٥٤﴾ إِنَّ ٱلَّذِينَ تَوَلَّوۡاْ مِنكُمۡ يَوۡمَ ٱلۡتَقَى ٱلۡجَمۡعَانِ إِنَّمَا ٱسۡتَزَلَّهُمُ ٱلشَّيۡطَٰنُ بِبَعۡضِ مَا كَسَبُواْۖ وَلَقَدۡ عَفَا ٱللَّهُ عَنۡهُمۡۗ إِنَّ ٱللَّهَ غَفُورٌ حَلِيمٞ ﴿١٥٥﴾", "w": [["أمنة نعاساً", "الأمنة: الأمن، والنعاس: استرخاء يصيب الجسم قبل النوم."], ["يغشى طائفة منكم", "يصيب المؤمنين ليستريحوا، ولا يصيب المنافقين."], ["أهمّتهم أنفسهم", "لا يفكرون إلا في نجاة أنفسهم، غير مكترثين بما أصاب رسول الله ﷺ وأصحابه."], ["ظن الجاهلية", "اعتقادهم أن النبي ﷺ قُتل، أو أنه لا يُنصر."], ["هل لنا من الأمر", "ما لنا من الأمر من شيء."], ["ما لا يبدون لك", "ما لا يُظهرون لك."], ["لبرز الذين", "لخرجوا من المدينة ظاهرين ليلقوا مصارعهم هناك."], ["كُتب عليهم القتل", "في كتاب المقادير، أي اللوح المحفوظ."], ["مضاجعهم", "جمع مضجع، والمراد المكان الذي صُرعوا فيه."], ["وليمحّص", "التمحيص: التمييز، كإظهار الإيمان من النفاق."], ["استزلّهم الشيطان", "أوقعهم في الزلل، وهو الخطيئة التي كانت الفرار من الجهاد."]], "m": "أخبر الله عن أمور عظام: أنه بعد الغم أنزل على أهل اليقين خاصة أمناً كاملاً، فذهب الخوف عنهم حتى إن أحدهم لينام والسيف في يده فيسقط ثم يتناوله. وأن أهل الشك والنفاق حرمهم الله من تلك الأمنة، فما زال الخوف يقطع قلوبهم، لا يفكرون إلا في نجاة أنفسهم. وكشف سرائرهم: يظنّون بالله غير الحق ظنّ الجاهلية، أن الإسلام باطل وأن المؤمنين سيُهزمون وينتهي الإسلام. ويقولون سراً: هل لنا من الأمر من شيء؟ أي لو كان الأمر لنا ما خرجنا ولا أصابنا ما أصابنا، فأمر رسوله ﷺ أن يردّ: إن الأمر كله لله. ويخفون في أنفسهم من الكفر والبغض ما لا يبدون، ويقولون: لو كان لنا من الأمر شيء ما قُتلنا هاهنا، فأمره أن يقول: لو كنتم في بيوتكم لخرج الذين كُتب عليهم القتل إلى مصارعهم، وليختبر الله ما في صدوركم ويميّز ما في قلوبكم. ثم أخبر أن الذين تولّوا يوم التقى الجمعان إنما أوقعهم الشيطان في هذه الزلّة ببعض ذنوب كانت لهم، ولقد عفا الله عنهم؛ لأنه غفور حليم يمهل عبده حتى يتوب فيتوب عليه.", "h": ["إكرام الله تعالى لأوليائه بالأمان الذي أنزله في قلوبهم.", "إهانة الله تعالى لأعدائه بحرمانهم مما أكرم به أولياءه وهم في مكان واحد.", "تقرير مبدأ القضاء والقدر، وأن من كُتب موته في مكان لا بد أن يموت فيه.", "أفعال الله تعالى لا تخلو أبداً من حِكم عالية، فيجب التسليم لله والرضا بأفعاله في خلقه.", "الذنب يولّد الذنب، والسيئة تتولد عنها سيئة أخرى، فلذا وجبت التوبة من الذنب فوراً."], "k": "«إنما استزلّهم الشيطان ببعض ما كسبوا»… هل ذنبٌ صغير أهملته اليوم يجرّني إلى ما هو أكبر؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 59;
insert into public.tdb_cards(topic, i, body) select 59, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٤٩ – ١٥١", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِن تُطِيعُواْ ٱلَّذِينَ كَفَرُواْ يَرُدُّوكُمۡ عَلَىٰٓ أَعۡقَٰبِكُمۡ فَتَنقَلِبُواْ خَٰسِرِينَ ﴿١٤٩﴾ بَلِ ٱللَّهُ مَوۡلَىٰكُمۡۖ وَهُوَ خَيۡرُ ٱلنَّـٰصِرِينَ ﴿١٥٠﴾ سَنُلۡقِي فِي قُلُوبِ ٱلَّذِينَ كَفَرُواْ ٱلرُّعۡبَ بِمَآ أَشۡرَكُواْ بِٱللَّهِ مَا لَمۡ يُنَزِّلۡ بِهِۦ سُلۡطَٰنٗاۖ وَمَأۡوَىٰهُمُ ٱلنَّارُۖ وَبِئۡسَ مَثۡوَى ٱلظَّـٰلِمِينَ ﴿١٥١﴾", "w": [["إن تطيعوا الذين كفروا", "المراد قبول قولهم والأخذ بإرشاداتهم."], ["يردّوكم على أعقابكم", "يرجعوكم إلى الكفر بعد الإيمان."], ["خاسرين", "فاقدين لكل خير في الدنيا، ولأنفسكم وأهليكم يوم القيامة."], ["بل الله مولاكم", "بل أطيعوا الله ربكم ووليكم، فإنه خير من يُطاع وأحق من يُطاع."], ["الرعب", "شدة الخوف من توقّع الهزيمة والمكروه."], ["مأواهم", "مقرّ إيوائهم ونزولهم."], ["مثوى", "مكان الإقامة والاستقرار."], ["الظالمين", "المشركين الذين أطاعوا غير الله وعبدوا سواه."]], "m": "ما زال السياق في أحداث أحد؛ رُوي أن بعض المنافقين لما رأى هزيمة المؤمنين قال: ارجعوا إلى دينكم وإخوانكم، ولو كان محمد نبياً لما قُتل. فحذّر الله المؤمنين من طاعة الكافرين: إن تطيعوهم يردّوكم على أعقابكم فتنقلبوا خاسرين؛ فهم يقترحون ما ظاهره النصح وباطنه الغش والخديعة، وهذا النهي وإن نزل في حالة خاصة فهو عام في المسلمين على مدى الحياة. ثم أمرهم بطاعته فهو مولاهم وأحق بطاعتهم، وإن أرادوا النصر فهو خير الناصرين، فليطلبوه منه بطاعته. ثم بشّرهم بأنه سيلقي في قلوب الكافرين الرعب حتى يتمكّنوا منهم، بسبب إشراكهم به آلهة لم ينزل بعبادتها حجة ولا سلطاناً، ومأواهم النار، وبئس مثوى الظالمين.", "h": ["تحريم طاعة الكافرين في حال الاختيار.", "بيان السر في تحريم طاعة الكافرين، وهو أنه يترتب عليها الردة والعياذ بالله.", "بيان قاعدة: من طلب النصر من غير الله أذلّه الله.", "وعد الله المؤمنين بنصرهم بعد إلقاء الرعب في قلوب أعدائهم؛ إذ همّ أبو سفيان بالعودة إلى المدينة بعد انصرافه من أحد، ثم ألقى الله في قلبه الرعب فعدل عن ذلك.", "بطلان كل دعوى ما لم يكن لأصحابها حجة، وهي المعبَّر عنها بالسلطان في الآية."], "k": "لمن أستمع حين أتخذ قراراتي؟ وهل يوافق ما يشيرون به أمرَ الله؟"}, {"lbl": "الآيتان ١٥٢ – ١٥٣", "q": "وَلَقَدۡ صَدَقَكُمُ ٱللَّهُ وَعۡدَهُۥٓ إِذۡ تَحُسُّونَهُم بِإِذۡنِهِۦۖ حَتَّىٰٓ إِذَا فَشِلۡتُمۡ وَتَنَٰزَعۡتُمۡ فِي ٱلۡأَمۡرِ وَعَصَيۡتُم مِّنۢ بَعۡدِ مَآ أَرَىٰكُم مَّا تُحِبُّونَۚ مِنكُم مَّن يُرِيدُ ٱلدُّنۡيَا وَمِنكُم مَّن يُرِيدُ ٱلۡأٓخِرَةَۚ ثُمَّ صَرَفَكُمۡ عَنۡهُمۡ لِيَبۡتَلِيَكُمۡۖ وَلَقَدۡ عَفَا عَنكُمۡۗ وَٱللَّهُ ذُو فَضۡلٍ عَلَى ٱلۡمُؤۡمِنِينَ ﴿١٥٢﴾ ۞إِذۡ تُصۡعِدُونَ وَلَا تَلۡوُۥنَ عَلَىٰٓ أَحَدٖ وَٱلرَّسُولُ يَدۡعُوكُمۡ فِيٓ أُخۡرَىٰكُمۡ فَأَثَٰبَكُمۡ غَمَّۢا بِغَمّٖ لِّكَيۡلَا تَحۡزَنُواْ عَلَىٰ مَا فَاتَكُمۡ وَلَا مَآ أَصَٰبَكُمۡۗ وَٱللَّهُ خَبِيرُۢ بِمَا تَعۡمَلُونَ ﴿١٥٣﴾", "w": [["صدقكم الله وعده", "أنجز لكم ما وعدكم على لسان رسوله ﷺ بقوله للرماة: اثبتوا أماكنكم فإنا لا نزال غالبين ما ثبتّم."], ["تحسّونهم", "تقتلونهم."], ["بإذنه", "بإذنه لكم في قتالهم وإعانته لكم على ذلك."], ["فشلتم", "ضعفتم وجبنتم عن القتال."], ["وتنازعتم في الأمر", "في أمركم وشأنكم."], ["تُصعدون", "تذهبون في الأرض فارّين من المعركة."], ["ولا تلوون على أحد", "لا تلتفتون إلى أحد."], ["والرسول يدعوكم في أخراكم", "يناديكم من خلفكم: إليّ عباد الله، ارجعوا."], ["فأثابكم غمّاً بغم", "جزاكم على معصيتكم وفراركم غمّاً على غمّ، والغمّ: ألم النفس وضيق الصدر."], ["ولا ما أصابكم", "من الموت والجراحات والآلام."]], "m": "لما بوّأ النبي ﷺ الرماة مقاعدهم، وكانوا ثلاثين رامياً عليهم عبد الله بن جبير، أمرهم ألا يبرحوا أماكنهم كيفما كانت الحال. ودارت المعركة فأنجز الله وعده، ففرّ المشركون والمؤمنون يقتلونهم بإذن الله. فلما رأى الرماة الهزيمة والمؤمنون يجمعون الغنائم قالوا: ما قيمة بقائنا هنا؟ فذكّرهم قائدهم بأمر رسول الله ﷺ، فتأوّلوه ونزلوا. وكان على خيل المشركين خالد بن الوليد، فلما رأى الرماة أخلّوا مراكزهم كرّ عليهم فاحتلّ أماكنهم وقتل من بقي ورمى المسلمين من ظهورهم، فوقعت الكارثة: قُتل سبعون من المؤمنين منهم حمزة، وجُرح رسول الله ﷺ، وصاح الشيطان: إن محمداً قد مات، ففرّ المؤمنون إلا قليلاً. وهذا معنى: «حتى إذا فشلتم وتنازعتم في الأمر وعصيتم من بعد ما أراكم ما تحبون»، فمنكم من يريد الدنيا وهم الذين نزلوا للغنائم، ومنكم من يريد الآخرة وهم ابن جبير ومن صبر معه حتى استُشهدوا. ثم صرفكم عنهم ليختبركم فيظهر الصادق من المنافق، ولقد عفا عنكم، ولو شاء لسلّط عليكم المشركين فاستأصلوكم. ثم صوّر حالهم وهم يفرّون في الوادي والرسول ﷺ يدعوهم من خلفهم، فجزاهم غمّاً على غمّ: غمّ فوات النصر والغنيمة، ثم غمّ القتل والجراحات وإشاعة قتل النبي ﷺ، فأنساهم الغمُّ الثاني الأول، لكيلا يحزنوا على ما فاتهم ولا ما أصابهم، والله خبير بما يعملون.", "h": ["مخالفة القيادة الرشيدة والتنازع في حال الحرب يسبب الهزيمة المنكرة.", "معصية الله ورسوله والاختلافات بين أفراد الأمة تُعقب آثاراً سيئة، أخفّها عقوبة الدنيا بالهزائم وذهاب الدولة والسلطان.", "ما من مصيبة تصيب العبد إلا وعند الله ما هو أعظم منها، فلذا يجب حمد الله على أنها لم تكن أعظم.", "ظاهر هزيمة أحد النقمة وباطنها النعمة؛ إذ علم المؤمنون أن النصر والهزيمة يتمّان حسب سنن إلهية، فما أصبحوا بعدها يغفلون تلك السنن أو يهملونها.", "معصية الرسول ﷺ مرة واحدة في شيء واحد ترتّب عليها آلام وجراحات وقتل وهزائم وفوات خير كثير، فكيف بالذين يعصونه طوال حياتهم في كل أوامره ونواهيه وهم آمنون غير خائفين؟"], "k": "معصية واحدة غيّرت نتيجة معركة… فما المعصية التي أستهين بها وأنا آمن؟"}, {"lbl": "الآيتان ١٥٤ – ١٥٥", "q": "ثُمَّ أَنزَلَ عَلَيۡكُم مِّنۢ بَعۡدِ ٱلۡغَمِّ أَمَنَةٗ نُّعَاسٗا يَغۡشَىٰ طَآئِفَةٗ مِّنكُمۡۖ وَطَآئِفَةٞ قَدۡ أَهَمَّتۡهُمۡ أَنفُسُهُمۡ يَظُنُّونَ بِٱللَّهِ غَيۡرَ ٱلۡحَقِّ ظَنَّ ٱلۡجَٰهِلِيَّةِۖ يَقُولُونَ هَل لَّنَا مِنَ ٱلۡأَمۡرِ مِن شَيۡءٖۗ قُلۡ إِنَّ ٱلۡأَمۡرَ كُلَّهُۥ لِلَّهِۗ يُخۡفُونَ فِيٓ أَنفُسِهِم مَّا لَا يُبۡدُونَ لَكَۖ يَقُولُونَ لَوۡ كَانَ لَنَا مِنَ ٱلۡأَمۡرِ شَيۡءٞ مَّا قُتِلۡنَا هَٰهُنَاۗ قُل لَّوۡ كُنتُمۡ فِي بُيُوتِكُمۡ لَبَرَزَ ٱلَّذِينَ كُتِبَ عَلَيۡهِمُ ٱلۡقَتۡلُ إِلَىٰ مَضَاجِعِهِمۡۖ وَلِيَبۡتَلِيَ ٱللَّهُ مَا فِي صُدُورِكُمۡ وَلِيُمَحِّصَ مَا فِي قُلُوبِكُمۡۚ وَٱللَّهُ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ ﴿١٥٤﴾ إِنَّ ٱلَّذِينَ تَوَلَّوۡاْ مِنكُمۡ يَوۡمَ ٱلۡتَقَى ٱلۡجَمۡعَانِ إِنَّمَا ٱسۡتَزَلَّهُمُ ٱلشَّيۡطَٰنُ بِبَعۡضِ مَا كَسَبُواْۖ وَلَقَدۡ عَفَا ٱللَّهُ عَنۡهُمۡۗ إِنَّ ٱللَّهَ غَفُورٌ حَلِيمٞ ﴿١٥٥﴾", "w": [["أمنة نعاساً", "الأمنة: الأمن، والنعاس: استرخاء يصيب الجسم قبل النوم."], ["يغشى طائفة منكم", "يصيب المؤمنين ليستريحوا، ولا يصيب المنافقين."], ["أهمّتهم أنفسهم", "لا يفكرون إلا في نجاة أنفسهم، غير مكترثين بما أصاب رسول الله ﷺ وأصحابه."], ["ظن الجاهلية", "اعتقادهم أن النبي ﷺ قُتل، أو أنه لا يُنصر."], ["هل لنا من الأمر", "ما لنا من الأمر من شيء."], ["ما لا يبدون لك", "ما لا يُظهرون لك."], ["لبرز الذين", "لخرجوا من المدينة ظاهرين ليلقوا مصارعهم هناك."], ["كُتب عليهم القتل", "في كتاب المقادير، أي اللوح المحفوظ."], ["مضاجعهم", "جمع مضجع، والمراد المكان الذي صُرعوا فيه."], ["وليمحّص", "التمحيص: التمييز، كإظهار الإيمان من النفاق."], ["استزلّهم الشيطان", "أوقعهم في الزلل، وهو الخطيئة التي كانت الفرار من الجهاد."]], "m": "أخبر الله عن أمور عظام: أنه بعد الغم أنزل على أهل اليقين خاصة أمناً كاملاً، فذهب الخوف عنهم حتى إن أحدهم لينام والسيف في يده فيسقط ثم يتناوله. وأن أهل الشك والنفاق حرمهم الله من تلك الأمنة، فما زال الخوف يقطع قلوبهم، لا يفكرون إلا في نجاة أنفسهم. وكشف سرائرهم: يظنّون بالله غير الحق ظنّ الجاهلية، أن الإسلام باطل وأن المؤمنين سيُهزمون وينتهي الإسلام. ويقولون سراً: هل لنا من الأمر من شيء؟ أي لو كان الأمر لنا ما خرجنا ولا أصابنا ما أصابنا، فأمر رسوله ﷺ أن يردّ: إن الأمر كله لله. ويخفون في أنفسهم من الكفر والبغض ما لا يبدون، ويقولون: لو كان لنا من الأمر شيء ما قُتلنا هاهنا، فأمره أن يقول: لو كنتم في بيوتكم لخرج الذين كُتب عليهم القتل إلى مصارعهم، وليختبر الله ما في صدوركم ويميّز ما في قلوبكم. ثم أخبر أن الذين تولّوا يوم التقى الجمعان إنما أوقعهم الشيطان في هذه الزلّة ببعض ذنوب كانت لهم، ولقد عفا الله عنهم؛ لأنه غفور حليم يمهل عبده حتى يتوب فيتوب عليه.", "h": ["إكرام الله تعالى لأوليائه بالأمان الذي أنزله في قلوبهم.", "إهانة الله تعالى لأعدائه بحرمانهم مما أكرم به أولياءه وهم في مكان واحد.", "تقرير مبدأ القضاء والقدر، وأن من كُتب موته في مكان لا بد أن يموت فيه.", "أفعال الله تعالى لا تخلو أبداً من حِكم عالية، فيجب التسليم لله والرضا بأفعاله في خلقه.", "الذنب يولّد الذنب، والسيئة تتولد عنها سيئة أخرى، فلذا وجبت التوبة من الذنب فوراً."], "k": "«إنما استزلّهم الشيطان ببعض ما كسبوا»… هل ذنبٌ صغير أهملته اليوم يجرّني إلى ما هو أكبر؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (60, 3, 156, 164, 'سورة آل عمران ١٥٦ – ١٦٤', 'لا تكونوا كالذين كفروا، ورحمة النبي ﷺ ومشاورته', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 60) = $j$[{"lbl": "الآيات ١٥٦ – ١٥٨", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَكُونُواْ كَٱلَّذِينَ كَفَرُواْ وَقَالُواْ لِإِخۡوَٰنِهِمۡ إِذَا ضَرَبُواْ فِي ٱلۡأَرۡضِ أَوۡ كَانُواْ غُزّٗى لَّوۡ كَانُواْ عِندَنَا مَا مَاتُواْ وَمَا قُتِلُواْ لِيَجۡعَلَ ٱللَّهُ ذَٰلِكَ حَسۡرَةٗ فِي قُلُوبِهِمۡۗ وَٱللَّهُ يُحۡيِۦ وَيُمِيتُۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرٞ ﴿١٥٦﴾ وَلَئِن قُتِلۡتُمۡ فِي سَبِيلِ ٱللَّهِ أَوۡ مُتُّمۡ لَمَغۡفِرَةٞ مِّنَ ٱللَّهِ وَرَحۡمَةٌ خَيۡرٞ مِّمَّا يَجۡمَعُونَ ﴿١٥٧﴾ وَلَئِن مُّتُّمۡ أَوۡ قُتِلۡتُمۡ لَإِلَى ٱللَّهِ تُحۡشَرُونَ ﴿١٥٨﴾", "w": [["آمنوا", "صدّقوا الله ورسوله فيما أخبرا به من وعد ووعيد."], ["لإخوانهم", "أخوّة العقيدة لا النسب، وهي هنا أخوّة النفاق."], ["ضربوا في الأرض", "سافروا للتجارة غالباً."], ["غُزّى", "جمع غازٍ، وهو من يخرج للقتال."], ["حسرة", "ألم يأخذ بخناق النفس بسبب فوت مرغوب أو فقد محبوب."]], "m": "ما زال السياق في أحداث أحد ونتائجها، فنادى الله المؤمنين لينهاهم عن الاتصاف بصفات الكافرين النفسية، ومنها قولهم لإخوانهم في الكفر إذا سافروا لتجارة أو غزو فمات من مات أو قُتل: لو كانوا عندنا ما ماتوا وما قُتلوا؛ وهذا دالّ على نفسية الجهل، يجعله الله حسرات في قلوبهم تمزّقهم. وما درى أولئك أن الله يحيي ويميت، فلا السفر ولا القتال يميتان، ولا القعود في البيت جبناً يُحيي. والله بما تعملون بصير: وعد للمؤمنين إن انتهوا، ووعيد إن لم ينتهوا. ثم بشّرهم: إن قُتلوا في سبيل الله أو ماتوا غفر لهم ورحمهم، وذلك خير مما يجمع الكفار من حطام الدنيا الذي جعلهم يجبنون عن الخروج في سبيل الله، وأكّد ذلك بأنهم إن ماتوا أو قُتلوا فإلى الله يُحشرون، فيتمّ لهم جزاؤه.", "h": ["حرمة التشبّه بالكفار ظاهراً وباطناً.", "الندم يولّد الحسرات، والحسرة غمّ وكرب عظيمان، والمؤمن يدفع ذلك بذكر القضاء والقدر، فلا يأسى على ما فاته ولا يفرح بما آتاه من حطام الدنيا.", "موتةٌ في سبيل الله خير من الدنيا وما فيها."], "k": "كم مرة قلت: «لو كنت فعلت كذا لما حدث كذا»؟ وكيف أستبدلها بـ«قدّر الله وما شاء فعل»؟"}, {"lbl": "الآيتان ١٥٩ – ١٦٠", "q": "فَبِمَا رَحۡمَةٖ مِّنَ ٱللَّهِ لِنتَ لَهُمۡۖ وَلَوۡ كُنتَ فَظًّا غَلِيظَ ٱلۡقَلۡبِ لَٱنفَضُّواْ مِنۡ حَوۡلِكَۖ فَٱعۡفُ عَنۡهُمۡ وَٱسۡتَغۡفِرۡ لَهُمۡ وَشَاوِرۡهُمۡ فِي ٱلۡأَمۡرِۖ فَإِذَا عَزَمۡتَ فَتَوَكَّلۡ عَلَى ٱللَّهِۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُتَوَكِّلِينَ ﴿١٥٩﴾ إِن يَنصُرۡكُمُ ٱللَّهُ فَلَا غَالِبَ لَكُمۡۖ وَإِن يَخۡذُلۡكُمۡ فَمَن ذَا ٱلَّذِي يَنصُرُكُم مِّنۢ بَعۡدِهِۦۗ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ ﴿١٦٠﴾", "w": [["لنت لهم", "كنت رفيقاً بهم تعاملهم بالرفق واللطف."], ["فظاً غليظ القلب", "خشناً في معاملتك، شرساً في أخلاقك، وحاشاه ﷺ."], ["لانفضّوا", "لتفرّقوا وذهبوا تاركينك."], ["فاعف عنهم", "إن زلّوا أو أساؤوا."], ["وشاورهم في الأمر", "اطلب مشورتهم في الأمر ذي الأهمية كمسائل الحرب والسلم."]], "m": "ما زال السياق في الآداب والنتائج المترتبة على غزوة أحد، فأخبر الله عما وهب رسوله ﷺ من الكمال الخُلقي الذي هو قوام الأمر: فبرحمة من عندنا رحمناهم بها لنتَ لهم، ولو كنت قاسياً جافياً غليظ القلب لتفرّقوا عنك وحُرموا بذلك سعادة الدارين. وبناءً على هذا فاعفُ عن مسيئهم، واستغفر لمذنبهم، وشاور ذوي الرأي منهم، وإذا بدا لك رأي راجح المصلحة فاعزم على تنفيذه متوكلاً على ربك، فإنه يحب المتوكلين. والتوكل: الإقدام على فعل ما أمر الله به أو أذن فيه بعد إحضار الأسباب الضرورية له، ثم تفويض أمر النتائج إليه. ثم قرّر حقيقة كبرى: أن النصر بيد الله والخذلان كذلك، فلا يُطلب النصر إلا منه، ولا يُرهب الخذلان إلا منه، وطلب نصره بإنفاذ أمره بعد إعداد الأسباب، وتحاشي خذلانه بطاعته والتوكل عليه: «إن ينصركم الله فلا غالب لكم، وإن يخذلكم فمن ذا الذي ينصركم من بعده، وعلى الله فليتوكل المؤمنون».", "h": ["كمال رسول الله ﷺ الخُلقي.", "فضل الصحابة رضوان الله عليهم، وكرامتهم على ربهم سبحانه وتعالى.", "تقرير مبدأ المشورة بين الحاكم وأهل الحل والعقد في الأمة.", "فضل العزيمة الصادقة مقرونة بالتوكل على الله تعالى.", "طلب النصر من غير الله خذلان، والمنصور من نصره الله، والمخذول من خذله الله عز وجل."], "k": "«ولو كنت فظاً غليظ القلب لانفضّوا من حولك»… هل يقترب الناس مني أم ينفضّون بسبب أسلوبي؟"}, {"lbl": "الآيات ١٦١ – ١٦٤", "q": "وَمَا كَانَ لِنَبِيٍّ أَن يَغُلَّۚ وَمَن يَغۡلُلۡ يَأۡتِ بِمَا غَلَّ يَوۡمَ ٱلۡقِيَٰمَةِۚ ثُمَّ تُوَفَّىٰ كُلُّ نَفۡسٖ مَّا كَسَبَتۡ وَهُمۡ لَا يُظۡلَمُونَ ﴿١٦١﴾ أَفَمَنِ ٱتَّبَعَ رِضۡوَٰنَ ٱللَّهِ كَمَنۢ بَآءَ بِسَخَطٖ مِّنَ ٱللَّهِ وَمَأۡوَىٰهُ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمَصِيرُ ﴿١٦٢﴾ هُمۡ دَرَجَٰتٌ عِندَ ٱللَّهِۗ وَٱللَّهُ بَصِيرُۢ بِمَا يَعۡمَلُونَ ﴿١٦٣﴾ لَقَدۡ مَنَّ ٱللَّهُ عَلَى ٱلۡمُؤۡمِنِينَ إِذۡ بَعَثَ فِيهِمۡ رَسُولٗا مِّنۡ أَنفُسِهِمۡ يَتۡلُواْ عَلَيۡهِمۡ ءَايَٰتِهِۦ وَيُزَكِّيهِمۡ وَيُعَلِّمُهُمُ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَإِن كَانُواْ مِن قَبۡلُ لَفِي ضَلَٰلٖ مُّبِينٍ ﴿١٦٤﴾", "w": [["أن يغلّ", "يأخذ من الغنيمة خفية، والغلّ والغلول بمعنى السرقة من الغنائم قبل قسمتها."], ["توفّى", "تُجزى ما كسبته في الدنيا وافياً تاماً يوم القيامة."], ["رضوان الله", "المراد ما يوجب رضوانه من الإيمان والصدق والجهاد."], ["بسخط من الله", "غضبه الشديد على الفاسقين عن أمره، المؤذين لرسوله ﷺ."], ["لقد منّ", "أنعم وتفضّل."], ["رسولاً من أنفسهم", "محمد ﷺ."], ["ويزكيهم", "بما يرشدهم إليه من الأعمال الصالحة والأخلاق الفاضلة والآداب العالية."], ["الحكمة", "كل قول صالح نافع، ومنه السنة النبوية."]], "m": "الغلول: أخذ المرء شيئاً من الغنائم قبل قسمتها، وما دام السياق في غزوة أحد فالمناسبة قائمة. فنفى الله أن يكون من شأن الأنبياء الغلول، وضمن ذلك أن أتباعهم يحرم عليهم أن يغلّوا، ولذا قُرئ في السبع: «أن يُغَلّ»، أي يفعله أتباعه بأخذهم من الغنائم بغير إذنه. ثم ذكر عقوبة من يفعل: يأتِ بما غلّ يوم القيامة يحمله، حتى البقرة والشاة كما في الحديث، ثم تُجزى كل نفس بما كسبت وهم لا يُظلمون. ثم نفى أن يكون حال المتبع لرضوان الله بالإيمان والطاعة كحال من رجع بسخط من الله بالتكذيب والمعصية فكانت جهنم مأواه، وأهل الرضوان وأصحاب السخط متفاوتون في درجاتهم عند الله بحسب أثر أعمالهم في نفوسهم، والله بصير بما يعملون. ثم امتنّ على المؤمنين من العرب ببعثة رسوله ﷺ فيهم: يتلو عليهم آيات الله فيؤمنون ويكملون، ويزكيهم من أوضار الشرك وظلمة الكفر، ويعلّمهم الكتاب المتضمن للشرائع والهدايات، والحكمة وهي فهم أسرار الكتاب والسنة، وتتجلّى هذه النعمة أكثر لمن يذكر حال العرب في جاهليتهم.", "h": ["تحريم الغلول، وأنه من كبائر الذنوب.", "طلب رضوان الله واجب، وتجنّب سخطه واجب كذلك؛ والأول يكون بالإيمان وصالح الأعمال، والثاني بترك الشرك والمعاصي.", "الإسلام أكبر نعمة وأجلّها على المسلمين، فيجب شكرها بالعمل به والتقيّد بشرائعه وأحكامه.", "فضل العلم بالكتاب والسنة."], "k": "بعثة النبي ﷺ أعظم منّة عليّ… فكم حديثاً من سنته أعرفه وأعمل به؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 60;
insert into public.tdb_cards(topic, i, body) select 60, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٥٦ – ١٥٨", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَكُونُواْ كَٱلَّذِينَ كَفَرُواْ وَقَالُواْ لِإِخۡوَٰنِهِمۡ إِذَا ضَرَبُواْ فِي ٱلۡأَرۡضِ أَوۡ كَانُواْ غُزّٗى لَّوۡ كَانُواْ عِندَنَا مَا مَاتُواْ وَمَا قُتِلُواْ لِيَجۡعَلَ ٱللَّهُ ذَٰلِكَ حَسۡرَةٗ فِي قُلُوبِهِمۡۗ وَٱللَّهُ يُحۡيِۦ وَيُمِيتُۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرٞ ﴿١٥٦﴾ وَلَئِن قُتِلۡتُمۡ فِي سَبِيلِ ٱللَّهِ أَوۡ مُتُّمۡ لَمَغۡفِرَةٞ مِّنَ ٱللَّهِ وَرَحۡمَةٌ خَيۡرٞ مِّمَّا يَجۡمَعُونَ ﴿١٥٧﴾ وَلَئِن مُّتُّمۡ أَوۡ قُتِلۡتُمۡ لَإِلَى ٱللَّهِ تُحۡشَرُونَ ﴿١٥٨﴾", "w": [["آمنوا", "صدّقوا الله ورسوله فيما أخبرا به من وعد ووعيد."], ["لإخوانهم", "أخوّة العقيدة لا النسب، وهي هنا أخوّة النفاق."], ["ضربوا في الأرض", "سافروا للتجارة غالباً."], ["غُزّى", "جمع غازٍ، وهو من يخرج للقتال."], ["حسرة", "ألم يأخذ بخناق النفس بسبب فوت مرغوب أو فقد محبوب."]], "m": "ما زال السياق في أحداث أحد ونتائجها، فنادى الله المؤمنين لينهاهم عن الاتصاف بصفات الكافرين النفسية، ومنها قولهم لإخوانهم في الكفر إذا سافروا لتجارة أو غزو فمات من مات أو قُتل: لو كانوا عندنا ما ماتوا وما قُتلوا؛ وهذا دالّ على نفسية الجهل، يجعله الله حسرات في قلوبهم تمزّقهم. وما درى أولئك أن الله يحيي ويميت، فلا السفر ولا القتال يميتان، ولا القعود في البيت جبناً يُحيي. والله بما تعملون بصير: وعد للمؤمنين إن انتهوا، ووعيد إن لم ينتهوا. ثم بشّرهم: إن قُتلوا في سبيل الله أو ماتوا غفر لهم ورحمهم، وذلك خير مما يجمع الكفار من حطام الدنيا الذي جعلهم يجبنون عن الخروج في سبيل الله، وأكّد ذلك بأنهم إن ماتوا أو قُتلوا فإلى الله يُحشرون، فيتمّ لهم جزاؤه.", "h": ["حرمة التشبّه بالكفار ظاهراً وباطناً.", "الندم يولّد الحسرات، والحسرة غمّ وكرب عظيمان، والمؤمن يدفع ذلك بذكر القضاء والقدر، فلا يأسى على ما فاته ولا يفرح بما آتاه من حطام الدنيا.", "موتةٌ في سبيل الله خير من الدنيا وما فيها."], "k": "كم مرة قلت: «لو كنت فعلت كذا لما حدث كذا»؟ وكيف أستبدلها بـ«قدّر الله وما شاء فعل»؟"}, {"lbl": "الآيتان ١٥٩ – ١٦٠", "q": "فَبِمَا رَحۡمَةٖ مِّنَ ٱللَّهِ لِنتَ لَهُمۡۖ وَلَوۡ كُنتَ فَظًّا غَلِيظَ ٱلۡقَلۡبِ لَٱنفَضُّواْ مِنۡ حَوۡلِكَۖ فَٱعۡفُ عَنۡهُمۡ وَٱسۡتَغۡفِرۡ لَهُمۡ وَشَاوِرۡهُمۡ فِي ٱلۡأَمۡرِۖ فَإِذَا عَزَمۡتَ فَتَوَكَّلۡ عَلَى ٱللَّهِۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُتَوَكِّلِينَ ﴿١٥٩﴾ إِن يَنصُرۡكُمُ ٱللَّهُ فَلَا غَالِبَ لَكُمۡۖ وَإِن يَخۡذُلۡكُمۡ فَمَن ذَا ٱلَّذِي يَنصُرُكُم مِّنۢ بَعۡدِهِۦۗ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ ﴿١٦٠﴾", "w": [["لنت لهم", "كنت رفيقاً بهم تعاملهم بالرفق واللطف."], ["فظاً غليظ القلب", "خشناً في معاملتك، شرساً في أخلاقك، وحاشاه ﷺ."], ["لانفضّوا", "لتفرّقوا وذهبوا تاركينك."], ["فاعف عنهم", "إن زلّوا أو أساؤوا."], ["وشاورهم في الأمر", "اطلب مشورتهم في الأمر ذي الأهمية كمسائل الحرب والسلم."]], "m": "ما زال السياق في الآداب والنتائج المترتبة على غزوة أحد، فأخبر الله عما وهب رسوله ﷺ من الكمال الخُلقي الذي هو قوام الأمر: فبرحمة من عندنا رحمناهم بها لنتَ لهم، ولو كنت قاسياً جافياً غليظ القلب لتفرّقوا عنك وحُرموا بذلك سعادة الدارين. وبناءً على هذا فاعفُ عن مسيئهم، واستغفر لمذنبهم، وشاور ذوي الرأي منهم، وإذا بدا لك رأي راجح المصلحة فاعزم على تنفيذه متوكلاً على ربك، فإنه يحب المتوكلين. والتوكل: الإقدام على فعل ما أمر الله به أو أذن فيه بعد إحضار الأسباب الضرورية له، ثم تفويض أمر النتائج إليه. ثم قرّر حقيقة كبرى: أن النصر بيد الله والخذلان كذلك، فلا يُطلب النصر إلا منه، ولا يُرهب الخذلان إلا منه، وطلب نصره بإنفاذ أمره بعد إعداد الأسباب، وتحاشي خذلانه بطاعته والتوكل عليه: «إن ينصركم الله فلا غالب لكم، وإن يخذلكم فمن ذا الذي ينصركم من بعده، وعلى الله فليتوكل المؤمنون».", "h": ["كمال رسول الله ﷺ الخُلقي.", "فضل الصحابة رضوان الله عليهم، وكرامتهم على ربهم سبحانه وتعالى.", "تقرير مبدأ المشورة بين الحاكم وأهل الحل والعقد في الأمة.", "فضل العزيمة الصادقة مقرونة بالتوكل على الله تعالى.", "طلب النصر من غير الله خذلان، والمنصور من نصره الله، والمخذول من خذله الله عز وجل."], "k": "«ولو كنت فظاً غليظ القلب لانفضّوا من حولك»… هل يقترب الناس مني أم ينفضّون بسبب أسلوبي؟"}, {"lbl": "الآيات ١٦١ – ١٦٤", "q": "وَمَا كَانَ لِنَبِيٍّ أَن يَغُلَّۚ وَمَن يَغۡلُلۡ يَأۡتِ بِمَا غَلَّ يَوۡمَ ٱلۡقِيَٰمَةِۚ ثُمَّ تُوَفَّىٰ كُلُّ نَفۡسٖ مَّا كَسَبَتۡ وَهُمۡ لَا يُظۡلَمُونَ ﴿١٦١﴾ أَفَمَنِ ٱتَّبَعَ رِضۡوَٰنَ ٱللَّهِ كَمَنۢ بَآءَ بِسَخَطٖ مِّنَ ٱللَّهِ وَمَأۡوَىٰهُ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمَصِيرُ ﴿١٦٢﴾ هُمۡ دَرَجَٰتٌ عِندَ ٱللَّهِۗ وَٱللَّهُ بَصِيرُۢ بِمَا يَعۡمَلُونَ ﴿١٦٣﴾ لَقَدۡ مَنَّ ٱللَّهُ عَلَى ٱلۡمُؤۡمِنِينَ إِذۡ بَعَثَ فِيهِمۡ رَسُولٗا مِّنۡ أَنفُسِهِمۡ يَتۡلُواْ عَلَيۡهِمۡ ءَايَٰتِهِۦ وَيُزَكِّيهِمۡ وَيُعَلِّمُهُمُ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَإِن كَانُواْ مِن قَبۡلُ لَفِي ضَلَٰلٖ مُّبِينٍ ﴿١٦٤﴾", "w": [["أن يغلّ", "يأخذ من الغنيمة خفية، والغلّ والغلول بمعنى السرقة من الغنائم قبل قسمتها."], ["توفّى", "تُجزى ما كسبته في الدنيا وافياً تاماً يوم القيامة."], ["رضوان الله", "المراد ما يوجب رضوانه من الإيمان والصدق والجهاد."], ["بسخط من الله", "غضبه الشديد على الفاسقين عن أمره، المؤذين لرسوله ﷺ."], ["لقد منّ", "أنعم وتفضّل."], ["رسولاً من أنفسهم", "محمد ﷺ."], ["ويزكيهم", "بما يرشدهم إليه من الأعمال الصالحة والأخلاق الفاضلة والآداب العالية."], ["الحكمة", "كل قول صالح نافع، ومنه السنة النبوية."]], "m": "الغلول: أخذ المرء شيئاً من الغنائم قبل قسمتها، وما دام السياق في غزوة أحد فالمناسبة قائمة. فنفى الله أن يكون من شأن الأنبياء الغلول، وضمن ذلك أن أتباعهم يحرم عليهم أن يغلّوا، ولذا قُرئ في السبع: «أن يُغَلّ»، أي يفعله أتباعه بأخذهم من الغنائم بغير إذنه. ثم ذكر عقوبة من يفعل: يأتِ بما غلّ يوم القيامة يحمله، حتى البقرة والشاة كما في الحديث، ثم تُجزى كل نفس بما كسبت وهم لا يُظلمون. ثم نفى أن يكون حال المتبع لرضوان الله بالإيمان والطاعة كحال من رجع بسخط من الله بالتكذيب والمعصية فكانت جهنم مأواه، وأهل الرضوان وأصحاب السخط متفاوتون في درجاتهم عند الله بحسب أثر أعمالهم في نفوسهم، والله بصير بما يعملون. ثم امتنّ على المؤمنين من العرب ببعثة رسوله ﷺ فيهم: يتلو عليهم آيات الله فيؤمنون ويكملون، ويزكيهم من أوضار الشرك وظلمة الكفر، ويعلّمهم الكتاب المتضمن للشرائع والهدايات، والحكمة وهي فهم أسرار الكتاب والسنة، وتتجلّى هذه النعمة أكثر لمن يذكر حال العرب في جاهليتهم.", "h": ["تحريم الغلول، وأنه من كبائر الذنوب.", "طلب رضوان الله واجب، وتجنّب سخطه واجب كذلك؛ والأول يكون بالإيمان وصالح الأعمال، والثاني بترك الشرك والمعاصي.", "الإسلام أكبر نعمة وأجلّها على المسلمين، فيجب شكرها بالعمل به والتقيّد بشرائعه وأحكامه.", "فضل العلم بالكتاب والسنة."], "k": "بعثة النبي ﷺ أعظم منّة عليّ… فكم حديثاً من سنته أعرفه وأعمل به؟"}]$j$::jsonb) with ordinality x(e, i);
select n, title, pub, (select count(*) from public.tdb_cards c where c.topic=t.n) cards from public.tdb_topics t where n>=36 order by n;